window.CHAPTERS=window.CHAPTERS||{};window.CHAPTERS["bc32"]={"id": "bc32", "title": "32. RNA的生物合成和加工", "sub": "朱圣庚《生物化学》第4版 · 第32章", "sub2": "第32章 · 全量PPT/笔记页 + 本页考点 + 课后题", "modules": [{"i": 0, "name": "老师PPT逐页（中文，93页）", "slides": [{"i": 0, "sec": "第32章 RNA的生物合成和加工 · 中文PPT原图", "title": "第十一章 RNA的生物合成", "notes": "第十一章 RNA的生物合成", "points": [], "img": "assets/img/bc32ppt/s-01.jpg", "imageExplain": "中文PPT第1页；右侧为从PPT提取的文字，图片保留原始排版。", "fig": "中文PPT：RNA的生物合成和转录后加工.pdf", "page": 1}, {"i": 1, "sec": "第32章 RNA的生物合成和加工 · 中文PPT原图", "title": "转录 加工", "notes": "College of Life Sciences, CNU\n\n 转录 加工\nDNA RNA前体 成熟的\n RNA分子\n\n复\n制\n RNA （RNA病毒）\n\n 逆转录\nRNA DNA", "points": ["DNA RNA前体 成熟的", "RNA （RNA病毒）", "RNA DNA"], "img": "assets/img/bc32ppt/s-02.jpg", "imageExplain": "中文PPT第2页；右侧为从PPT提取的文字，图片保留原始排版。", "fig": "中文PPT：RNA的生物合成和转录后加工.pdf", "page": 2}, {"i": 2, "sec": "第32章 RNA的生物合成和加工 · 中文PPT原图", "title": "第一节 DNA指导下RNA的合成", "notes": "College of Life Sciences, CNU\n\n第一节 DNA指导下RNA的合成", "points": [], "img": "assets/img/bc32ppt/s-03.jpg", "imageExplain": "中文PPT第3页；右侧为从PPT提取的文字，图片保留原始排版。", "fig": "中文PPT：RNA的生物合成和转录后加工.pdf", "page": 3}, {"i": 3, "sec": "第32章 RNA的生物合成和加工 · 中文PPT原图", "title": "转录（transcription）", "notes": "College of Life Sciences, CNU\n\n转录（transcription）\n\n DNA指导下RNA的合成。", "points": ["DNA指导下RNA的合成。"], "img": "assets/img/bc32ppt/s-04.jpg", "imageExplain": "中文PPT第4页；右侧为从PPT提取的文字，图片保留原始排版。", "fig": "中文PPT：RNA的生物合成和转录后加工.pdf", "page": 4}, {"i": 4, "sec": "第32章 RNA的生物合成和加工 · 中文PPT原图", "title": "一、不对称转录", "notes": "College of Life Sciences, CNU\n一、不对称转录\n\n 转录时，DNA双链不是同时作为模板，而是\n 在一定条件下，只有一条链（或其上某些区域）\n 可作为转录的模板。\n\n ⚫ 编码链（coding strand，+ 链）\n 与转录出的RNA顺序相同的一条链（仅T代替U）\n\n ⚫ 模板链（template strand，- 链）\n 为RNA提供转录模板的链。", "points": ["转录时，DNA双链不是同时作为模板，而是", "在一定条件下，只有一条链（或其上某些区域）", "可作为转录的模板。", "编码链（coding strand，+ 链）"], "img": "assets/img/bc32ppt/s-05.jpg", "imageExplain": "中文PPT第5页；右侧为从PPT提取的文字，图片保留原始排版。", "fig": "中文PPT：RNA的生物合成和转录后加工.pdf", "page": 5}, {"i": 5, "sec": "第32章 RNA的生物合成和加工 · 中文PPT原图", "title": "一、编码链和模板链", "notes": "College of Life Sciences, CNU\n一、编码链和模板链\n⚫ 编码链（+ 链）: 与转录出的RNA顺序相同的一条链。\n （仅T代替U）\n⚫模板链（- 链）: 为RNA提供转录模板的链。\n\n 编码链（正链）\n\n 模板链（负链）\n\n 编码链（正链）\n 模板链（负链）", "points": ["编码链（+ 链）: 与转录出的RNA顺序相同的一条链。", "（仅T代替U）", "模板链（- 链）: 为RNA提供转录模板的链。", "编码链（正链）"], "img": "assets/img/bc32ppt/s-06.jpg", "imageExplain": "中文PPT第6页；右侧为从PPT提取的文字，图片保留原始排版。", "fig": "中文PPT：RNA的生物合成和转录后加工.pdf", "page": 6}, {"i": 6, "sec": "第32章 RNA的生物合成和加工 · 中文PPT原图", "title": "二、不对称转录", "notes": "College of Life Sciences, CNU\n二、不对称转录\n 转录时，DNA双链不是同时作为模板，而是在一定条件\n下，只有一条链（或其上某些区域）可作为转录的模板。\n\n⚫ 不是所有基因的编码链都位于DNA分子的同一条链上\n\n A B C D\n\n 编码链\n\n⚫ 基因的转录是有选择性的。\n - 并不是全部DNA都必须转录\n - 根据细胞实际需求，特定的基因“开放”或“关闭”，\n具复杂的调控机制。", "points": ["转录时，DNA双链不是同时作为模板，而是在一定条件", "下，只有一条链（或其上某些区域）可作为转录的模板。", "不是所有基因的编码链都位于DNA分子的同一条链上", "A B C D"], "img": "assets/img/bc32ppt/s-07.jpg", "imageExplain": "中文PPT第7页；右侧为从PPT提取的文字，图片保留原始排版。", "fig": "中文PPT：RNA的生物合成和转录后加工.pdf", "page": 7}, {"i": 7, "sec": "第32章 RNA的生物合成和加工 · 中文PPT原图", "title": "三、转录单位", "notes": "College of Life Sciences, CNU\n三、转录单位\n\n RNA的转录起始于DNA模板的一个特定位点，\n并在另一位点处终止，此转录区域称为转录单位。\n 例：为mRNA编码的转录单位\n •真核生物\n\n 转录单位 转录 mRNA 翻译 1种蛋白质\n （1个基因） （单顺反子）\n\n •原核生物\n转录单位 转录 翻译\n mRNA 多种蛋白质\n（多个基因） （多顺反子）", "points": ["RNA的转录起始于DNA模板的一个特定位点，", "并在另一位点处终止，此转录区域称为转录单位。", "例：为mRNA编码的转录单位", "转录单位 转录 mRNA 翻译 1种蛋白质"], "img": "assets/img/bc32ppt/s-08.jpg", "imageExplain": "中文PPT第8页；右侧为从PPT提取的文字，图片保留原始排版。", "fig": "中文PPT：RNA的生物合成和转录后加工.pdf", "page": 8}, {"i": 8, "sec": "第32章 RNA的生物合成和加工 · 中文PPT原图", "title": "四、 启动子和转录因子", "notes": "College of Life Sciences, CNU\n四、 启动子和转录因子\n\n• 启动子（promoter）\n 指 RNA聚合酶识别、结合和开始转录的一段\nDNA序列。具有特定的核苷酸顺序。\n\n• 转录因子（transcription factor）\n 指 RNA聚合酶起始转录需要的辅助因子（蛋白质）。", "points": ["启动子（promoter）", "指 RNA聚合酶识别、结合和开始转录的一段", "DNA序列。具有特定的核苷酸顺序。", "转录因子（transcription factor）"], "img": "assets/img/bc32ppt/s-09.jpg", "imageExplain": "中文PPT第9页；右侧为从PPT提取的文字，图片保留原始排版。", "fig": "中文PPT：RNA的生物合成和转录后加工.pdf", "page": 9}, {"i": 9, "sec": "第32章 RNA的生物合成和加工 · 中文PPT原图", "title": "启动子的鉴定---Footprint analysis （足迹法）", "notes": "College of Life Sciences, CNU\n启动子的鉴定---Footprint analysis （足迹法）\n\n （Lac 启动子）", "points": ["（Lac 启动子）"], "img": "assets/img/bc32ppt/s-10.jpg", "imageExplain": "中文PPT第10页；右侧为从PPT提取的文字，图片保留原始排版。", "fig": "中文PPT：RNA的生物合成和转录后加工.pdf", "page": 10}, {"i": 10, "sec": "第32章 RNA的生物合成和加工 · 中文PPT原图", "title": "❖ DNA序列的书写方式（编码链）", "notes": "College of Life Sciences, CNU\n\n❖ DNA序列的书写方式（编码链）\n\n5 +1 3\n 上游 下游\n upstream 转录起点 downstream", "points": ["5 +1 3", "upstream 转录起点 downstream"], "img": "assets/img/bc32ppt/s-11.jpg", "imageExplain": "中文PPT第11页；右侧为从PPT提取的文字，图片保留原始排版。", "fig": "中文PPT：RNA的生物合成和转录后加工.pdf", "page": 11}, {"i": 11, "sec": "第32章 RNA的生物合成和加工 · 中文PPT原图", "title": "1. 原核生物启动子结构特点和功能", "notes": "College of Life Sciences, CNU\n1. 原核生物启动子结构特点和功能\n\n -35 -10 +1\n 识别区 Pribnow box\n TTGACA TATAAT\n\n 6 bp保守序列 6 bp保守序列\n\n 提供RNA聚合酶 双链局部 转录起点\n 全酶识别的信号 解开区域 （第1个核苷酸参入的位置）", "points": ["35 -10 +1", "识别区 Pribnow box", "TTGACA TATAAT", "6 bp保守序列 6 bp保守序列"], "img": "assets/img/bc32ppt/s-12.jpg", "imageExplain": "中文PPT第12页；右侧为从PPT提取的文字，图片保留原始排版。", "fig": "中文PPT：RNA的生物合成和转录后加工.pdf", "page": 12}, {"i": 12, "sec": "第32章 RNA的生物合成和加工 · 中文PPT原图", "title": "E. coli 一些启动子的核苷酸序列", "notes": "College of Life Sciences, CNU\nE. coli 一些启动子的核苷酸序列", "points": [], "img": "assets/img/bc32ppt/s-13.jpg", "imageExplain": "中文PPT第13页；右侧为从PPT提取的文字，图片保留原始排版。", "fig": "中文PPT：RNA的生物合成和转录后加工.pdf", "page": 13}, {"i": 13, "sec": "第32章 RNA的生物合成和加工 · 中文PPT原图", "title": "2. 真核生物启动子结构特点和功能", "notes": "College of Life Sciences, CNU\n2. 真核生物启动子结构特点和功能\n\n 包括三类: 类别（Class）Ⅰ、Ⅱ、Ⅲ\n\n⚫ 类别I（由RNA聚合酶I 进行转录）\n\n 上游控制元件 核心启动子\n\n UBF1 SL1因子（四聚体）\n （单一肽链） (1TBP +3TAF)", "points": ["包括三类: 类别（Class）Ⅰ、Ⅱ、Ⅲ", "类别I（由RNA聚合酶I 进行转录）", "上游控制元件 核心启动子", "UBF1 SL1因子（四聚体）"], "img": "assets/img/bc32ppt/s-14.jpg", "imageExplain": "中文PPT第14页；右侧为从PPT提取的文字，图片保留原始排版。", "fig": "中文PPT：RNA的生物合成和转录后加工.pdf", "page": 14}, {"i": 14, "sec": "第32章 RNA的生物合成和加工 · 中文PPT原图", "title": "类别III（由RNA聚合酶III进行转录）", "notes": "College of Life Sciences, CNU\n⚫ 类别III（由RNA聚合酶III进行转录）\n\n（1）基因内启动子（下游启动子）\n类型I 中间元件\n +55 +80\n\n爪蟾 转录起点\n\n类型Ⅱ\n\n腺病毒RNA\n 转录起点\n\n（2）上游启动子\nsnRNA\n OCT PSE TATA 转录起点\n 八聚体框 邻近序列元件\n\n（有些snRNA由RNA聚合酶II进行转录）", "points": ["（1）基因内启动子（下游启动子）", "类型I 中间元件", "+55 +80", "爪蟾 转录起点"], "img": "assets/img/bc32ppt/s-15.jpg", "imageExplain": "中文PPT第15页；右侧为从PPT提取的文字，图片保留原始排版。", "fig": "中文PPT：RNA的生物合成和转录后加工.pdf", "page": 15}, {"i": 15, "sec": "第32章 RNA的生物合成和加工 · 中文PPT原图", "title": "类别II启动子（由RNA聚合酶II进行转录）", "notes": "⚫ 类别II启动子（由RNA聚合酶II进行转录）\n 顺式作用元件 转录因子\n +1 T\n⚫起始子(Inr) Py Py A N Py Py\n A\n\n 通用因子(TFⅡX)\n⚫TATA框 7bp, 位于-25 ~ -30bp处\n （6种：TFⅡD, A, B, F, E, H)\n\n⚫上游元件 CAAT 框 GCCAATCT CP1, CP2, NF-1\n 上游因子\n GC框 GGGCGG Sp1\n 八聚体框 ATGCAAAT Oct-1, Oct-2\n\n 激素应答元件 激素受体\n⚫应答元件 热休克因子 可诱导因子\n 热休克元件HSE\n …… ……", "points": ["顺式作用元件 转录因子", "起始子(Inr) Py Py A N Py Py", "通用因子(TFⅡX)", "TATA框 7bp, 位于-25 ~ -30bp处"], "img": "assets/img/bc32ppt/s-16.jpg", "imageExplain": "中文PPT第16页；右侧为从PPT提取的文字，图片保留原始排版。", "fig": "中文PPT：RNA的生物合成和转录后加工.pdf", "page": 16}, {"i": 16, "sec": "第32章 RNA的生物合成和加工 · 中文PPT原图", "title": "类别II启动子", "notes": "类别II启动子\n\n 上游元件 TATA框 起始子 核心启动子\n (基本启动子)\n\n 与上游因子结 RNA聚合酶II和通用因子 转录起点\n 合，调节转录 形成前起始复合物的主要\n 的效率 装配点\n\n应答元件 结合可诱导因子，对外界刺激和激素信号做出应答。", "points": ["上游元件 TATA框 起始子 核心启动子", "(基本启动子)", "与上游因子结 RNA聚合酶II和通用因子 转录起点", "合，调节转录 形成前起始复合物的主要"], "img": "assets/img/bc32ppt/s-17.jpg", "imageExplain": "中文PPT第17页；右侧为从PPT提取的文字，图片保留原始排版。", "fig": "中文PPT：RNA的生物合成和转录后加工.pdf", "page": 17}, {"i": 17, "sec": "第32章 RNA的生物合成和加工 · 中文PPT原图", "title": "人金属硫蛋白基因的调节区", "notes": "College of Life Sciences, CNU\n 人金属硫蛋白基因的调节区\n (p568-569)\n\n BLE\n GRE E-box BLE MRE MRE TRE MRE GC MRE TATA\n\n-260 -240 -220 -200 -180 -160 -140 -120 -100 -80 -60 -40 -20 0\n\n 类固醇\n 受体 USF AP2 AP2 AP1 Sp1\n\n MTF1 MTF1\n\n •通用因子与TATA框结合，Sp1与GC框结合\n •转录因子MTF１与金属应答元件（MRE）结合\n •上游因子AP1、AP2,、USF分别与TRE、BLE和E框结合", "points": ["(p568-569)", "GRE E-box BLE MRE MRE TRE MRE GC MRE TATA", "260 -240 -220 -200 -180 -160 -140 -120 -100 -80 -60 -40 -20 0", "受体 USF AP2 AP2 AP1 Sp1"], "img": "assets/img/bc32ppt/s-18.jpg", "imageExplain": "中文PPT第18页；右侧为从PPT提取的文字，图片保留原始排版。", "fig": "中文PPT：RNA的生物合成和转录后加工.pdf", "page": 18}, {"i": 18, "sec": "第32章 RNA的生物合成和加工 · 中文PPT原图", "title": "五、 终止子和终止因子", "notes": "College of Life Sciences, CNU\n五、 终止子和终止因子\n1. 终止子（terminator）：\n 提供转录终止信号的DNA序列。\n• 原核生物终止子在终止点前有一回文结构，其产生的RNA\n可形成发夹结构。该结构可被RNA聚合酶感受，从而使聚合\n酶减慢移动或停止转录。\n\n•大肠杆菌两类终止子：\n不依赖rho（）的终止子 回文结构内有一段富含G-C的\n（简单终止子） 序列，在终止点前有一系列T\n 核苷酸（+ 链）。\n 依赖rho（  ）的终止子", "points": ["1. 终止子（terminator）：", "提供转录终止信号的DNA序列。", "原核生物终止子在终止点前有一回文结构，其产生的RNA", "可形成发夹结构。该结构可被RNA聚合酶感受，从而使聚合"], "img": "assets/img/bc32ppt/s-19.jpg", "imageExplain": "中文PPT第19页；右侧为从PPT提取的文字，图片保留原始排版。", "fig": "中文PPT：RNA的生物合成和转录后加工.pdf", "page": 19}, {"i": 19, "sec": "第32章 RNA的生物合成和加工 · 中文PPT原图", "title": "E. coli trp 操纵子的终止位点", "notes": "College of Life Sciences, CNU\n E. coli trp 操纵子的终止位点\n 不依赖rho（）的终止子\n\n编码链（+链）\n\n模板链（-链）", "points": ["不依赖rho（）的终止子", "编码链（+链）", "模板链（-链）"], "img": "assets/img/bc32ppt/s-20.jpg", "imageExplain": "中文PPT第20页；右侧为从PPT提取的文字，图片保留原始排版。", "fig": "中文PPT：RNA的生物合成和转录后加工.pdf", "page": 20}, {"i": 20, "sec": "第32章 RNA的生物合成和加工 · 中文PPT原图", "title": "2. 终止因子(termination factor)", "notes": "College of Life Sciences, CNU\n2. 终止因子(termination factor)\n 协助RNA聚合酶识别终止信号的辅助因子\n （蛋白质）。\n\n原核生物：Nus A、Nus B、Nus E、NusG等蛋白\n\n •Nus A：可提高终止效率，促进RNA聚合酶在终止\n 子处的停顿。\n\n •NusB: 与NusE形成二聚体，促进对终止子的识别\n\n •NusG: 促进Nus因子与RNA聚合酶的装配", "points": ["协助RNA聚合酶识别终止信号的辅助因子", "（蛋白质）。", "原核生物：Nus A、Nus B、Nus E、NusG等蛋白", "Nus A：可提高终止效率，促进RNA聚合酶在终止"], "img": "assets/img/bc32ppt/s-21.jpg", "imageExplain": "中文PPT第21页；右侧为从PPT提取的文字，图片保留原始排版。", "fig": "中文PPT：RNA的生物合成和转录后加工.pdf", "page": 21}, {"i": 21, "sec": "第32章 RNA的生物合成和加工 · 中文PPT原图", "title": "五、原核生物RNA合成的分子机制", "notes": "College of Life Sciences, CNU\n五、原核生物RNA合成的分子机制\n\n •部位：核区\n •模板: 双链DNA的模板链\n •原料及能源： NTP (N: A, G, C, U)", "points": ["模板: 双链DNA的模板链", "原料及能源： NTP (N: A, G, C, U)"], "img": "assets/img/bc32ppt/s-22.jpg", "imageExplain": "中文PPT第22页；右侧为从PPT提取的文字，图片保留原始排版。", "fig": "中文PPT：RNA的生物合成和转录后加工.pdf", "page": 22}, {"i": 22, "sec": "第32章 RNA的生物合成和加工 · 中文PPT原图", "title": "(一) RNA聚合酶（DNA-directed RNA polymerase）", "notes": "College of Life Sciences, CNU\n(一) RNA聚合酶（DNA-directed RNA polymerase）\n • 反应式：\n DNA指导下的RNA聚合酶\n nNTP (NMP)n + nPPi\n DNA, Mg2+\n RNA片段\n\n • RNA聚合酶特点：\n - 需要4种NTP为底物，第一个底物通常为GTP或ATP\n - 需DNA模板\n - 聚合方向5→3（大肠杆菌40-50个核苷酸/S）\n - 不需要引物\n 逆反应去除错配核苷酸\n - 无外切酶活性\n (校对功能有限) RNA聚合酶熄火、倒退，切除几个核苷酸 (含错配)", "points": ["DNA指导下的RNA聚合酶", "nNTP (NMP)n + nPPi", "DNA, Mg2+", "RNA聚合酶特点："], "img": "assets/img/bc32ppt/s-23.jpg", "imageExplain": "中文PPT第23页；右侧为从PPT提取的文字，图片保留原始排版。", "fig": "中文PPT：RNA的生物合成和转录后加工.pdf", "page": 23}, {"i": 23, "sec": "第32章 RNA的生物合成和加工 · 中文PPT原图", "title": "RNA聚合酶结构", "notes": "College of Life Sciences, CNU\n\n⚫ RNA聚合酶结构\n（16nm 椭球体）\n\nMr. 460 000，具有5个亚基（2 σ），含Zn2+\n\n 2  （核心酶） 催化RNA链的延长\n\n σ （起始亚基） 识别启动子，促进转录的起始\n\n  功能未知，体外可以帮助变性\n 的RNA聚合酶恢复功能", "points": ["（16nm 椭球体）", "Mr. 460 000，具有5个亚基（2 σ），含Zn2+", "2  （核心酶） 催化RNA链的延长", "σ （起始亚基） 识别启动子，促进转录的起始"], "img": "assets/img/bc32ppt/s-24.jpg", "imageExplain": "中文PPT第24页；右侧为从PPT提取的文字，图片保留原始排版。", "fig": "中文PPT：RNA的生物合成和转录后加工.pdf", "page": 24}, {"i": 24, "sec": "第32章 RNA的生物合成和加工 · 中文PPT原图", "title": "转录泡", "notes": "College of Life Sciences, CNU\n转录泡", "points": [], "img": "assets/img/bc32ppt/s-25.jpg", "imageExplain": "中文PPT第25页；右侧为从PPT提取的文字，图片保留原始排版。", "fig": "中文PPT：RNA的生物合成和转录后加工.pdf", "page": 25}, {"i": 25, "sec": "第32章 RNA的生物合成和加工 · 中文PPT原图", "title": "（二）转录过程", "notes": "College of Life Sciences, CNU\n（二）转录过程\n 1. 模板的识别\n RNA聚合酶在因子的协助下结合\n 到启动子上，DNA双链局部打开，形\n 成转录泡。\n\n 2. 转录的起始\n （1）RNA聚合酶催化合成RNA链最\n 初的2 ~ 9个核苷酸。 加入的第一个\n 核苷酸通常为ATP或GTP。新生链5\n 端为pppA或pppG。\n （2）因子脱离核心酶\n\n 3.延伸\n 核心酶2 催化RNA链5→3延长。", "points": ["1. 模板的识别", "RNA聚合酶在因子的协助下结合", "到启动子上，DNA双链局部打开，形", "2. 转录的起始"], "img": "assets/img/bc32ppt/s-26.jpg", "imageExplain": "中文PPT第26页；右侧为从PPT提取的文字，图片保留原始排版。", "fig": "中文PPT：RNA的生物合成和转录后加工.pdf", "page": 26}, {"i": 26, "sec": "第32章 RNA的生物合成和加工 · 中文PPT原图", "title": "4.终止", "notes": "College of Life Sciences, CNU\n4.终止\n RNA聚合酶自身感知终止信\n号，且Nus A识别终止子，使转录\n终止，产物RNA链释放。\n\n 核心酶2 自模板脱落，重 异构化\n新与因子结合，参与下一次转录。\n\n 某些终止过程尚需ρ蛋白参与。\n\n不依赖的终止\n\n 终止", "points": ["RNA聚合酶自身感知终止信", "号，且Nus A识别终止子，使转录", "终止，产物RNA链释放。", "核心酶2 自模板脱落，重 异构化"], "img": "assets/img/bc32ppt/s-27.jpg", "imageExplain": "中文PPT第27页；右侧为从PPT提取的文字，图片保留原始排版。", "fig": "中文PPT：RNA的生物合成和转录后加工.pdf", "page": 27}, {"i": 27, "sec": "第32章 RNA的生物合成和加工 · 中文PPT原图", "title": "ρ 因子在转录终止中的作用", "notes": "College of Life Sciences, CNU\n ρ 因子在转录终止中的作用\n\n 3\n\n 5\n\nNTP酶活力\n\nRNA-DNA解螺旋酶活力", "points": ["NTP酶活力", "RNA-DNA解螺旋酶活力"], "img": "assets/img/bc32ppt/s-28.jpg", "imageExplain": "中文PPT第28页；右侧为从PPT提取的文字，图片保留原始排版。", "fig": "中文PPT：RNA的生物合成和转录后加工.pdf", "page": 28}, {"i": 28, "sec": "第32章 RNA的生物合成和加工 · 中文PPT原图", "title": "转录的起始", "notes": "College of Life Sciences, CNU\n转录的起始", "points": [], "img": "assets/img/bc32ppt/s-29.jpg", "imageExplain": "中文PPT第29页；右侧为从PPT提取的文字，图片保留原始排版。", "fig": "中文PPT：RNA的生物合成和转录后加工.pdf", "page": 29}, {"i": 29, "sec": "第32章 RNA的生物合成和加工 · 中文PPT原图", "title": "转录的起始与延伸", "notes": "College of Life Sciences, CNU\n转录的起始与延伸", "points": [], "img": "assets/img/bc32ppt/s-30.jpg", "imageExplain": "中文PPT第30页；右侧为从PPT提取的文字，图片保留原始排版。", "fig": "中文PPT：RNA的生物合成和转录后加工.pdf", "page": 30}, {"i": 30, "sec": "第32章 RNA的生物合成和加工 · 中文PPT原图", "title": "六、真核生物RNA的合成", "notes": "College of Life Sciences, CNU\n六、真核生物RNA的合成\n\n（一）RNA聚合酶\n Mr. 500 000，8-14个亚基，含Zn2+\n\n 对-鹅膏蕈碱的\n 酶 位置 产物(前体)\n 敏感性\n 5.8S, 18S, 和\n RNA聚合酶Ⅰ 核仁 不敏感\n 28SrRNA\n mRNA\nRNA聚合酶Ⅱ 核浆 敏感\n 大多数snRNA\n 小RNA（tRNA,\nRNA聚合酶Ⅲ 核浆 中等敏感\n 5SRNA等）", "points": ["（一）RNA聚合酶", "Mr. 500 000，8-14个亚基，含Zn2+", "对-鹅膏蕈碱的", "酶 位置 产物(前体)"], "img": "assets/img/bc32ppt/s-31.jpg", "imageExplain": "中文PPT第31页；右侧为从PPT提取的文字，图片保留原始排版。", "fig": "中文PPT：RNA的生物合成和转录后加工.pdf", "page": 31}, {"i": 31, "sec": "第32章 RNA的生物合成和加工 · 中文PPT原图", "title": "（二）合成过程", "notes": "College of Life Sciences, CNU\n（二）合成过程\n\n 转录过程分为装配、起始、延长、终止等阶段。\n\n1.装配\n\n 真核RNA聚合酶不能识别和结合启动子，需要与\n通用转录因子装配成结构复杂的前起始复合物，才能\n起始转录。\n\n 以Ⅱ类启动子起始复合物的装配为例，至少涉\n 及6种通用转录因子。", "points": ["转录过程分为装配、起始、延长、终止等阶段。", "真核RNA聚合酶不能识别和结合启动子，需要与", "通用转录因子装配成结构复杂的前起始复合物，才能", "以Ⅱ类启动子起始复合物的装配为例，至少涉"], "img": "assets/img/bc32ppt/s-32.jpg", "imageExplain": "中文PPT第32页；右侧为从PPT提取的文字，图片保留原始排版。", "fig": "中文PPT：RNA的生物合成和转录后加工.pdf", "page": 32}, {"i": 32, "sec": "第32章 RNA的生物合成和加工 · 中文PPT原图", "title": "真核生物类型II启动子的转录", "notes": "真核生物类型II启动子的转录\n College of Life Sciences, CNU\n 通用转录因子 (p563)\n TFⅡD 识别TATA框，促双链打开\n TFⅡA 稳定TFⅡD 与TATA框结合\n TFⅡB 结合TBP, 引进TFⅡF-PolⅡ\n TFⅡF 与PolⅡ结合, 参与解链\n TFⅡE 引入TFⅡH并提高其活性\n TFⅡH 解链、使 PolⅡ磷酸化, 清除\n 转录因子\n装配\n\n 终止 2. 起始\n起始 在前起始复合物的\n 延伸\n 作用下，DNA双链分开，\n 形成开放复合物，RNA\n 聚合酶Ⅱ开始催化RNA\n 链的合成，转录起始。", "points": ["通用转录因子 (p563)", "TFⅡD 识别TATA框，促双链打开", "TFⅡA 稳定TFⅡD 与TATA框结合", "TFⅡB 结合TBP, 引进TFⅡF-PolⅡ"], "img": "assets/img/bc32ppt/s-33.jpg", "imageExplain": "中文PPT第33页；右侧为从PPT提取的文字，图片保留原始排版。", "fig": "中文PPT：RNA的生物合成和转录后加工.pdf", "page": 33}, {"i": 33, "sec": "第32章 RNA的生物合成和加工 · 中文PPT原图", "title": "3. 延伸", "notes": "College of Life Sciences, CNU\n\n3. 延伸\n 转录起始后，RNA聚合酶Ⅱ被磷酸化，构象发生改变，\n脱离起始复合物，沿着模板链继续滑动。\n\n 启动子处通用转录因子被清除，在延伸因子的促进下，\nRNA聚合酶Ⅱ催化RNA链的延伸。\n\n 4. 终止\n 真核生物RNA的原初转录物3 端很快被加工，所以很难\n对终止序列进行研究。目前关于真核生物转录终止过程尚不\n清楚。\n RNA聚合酶Ⅱ去磷酸化，参与下一轮催化。", "points": ["转录起始后，RNA聚合酶Ⅱ被磷酸化，构象发生改变，", "脱离起始复合物，沿着模板链继续滑动。", "启动子处通用转录因子被清除，在延伸因子的促进下，", "RNA聚合酶Ⅱ催化RNA链的延伸。"], "img": "assets/img/bc32ppt/s-34.jpg", "imageExplain": "中文PPT第34页；右侧为从PPT提取的文字，图片保留原始排版。", "fig": "中文PPT：RNA的生物合成和转录后加工.pdf", "page": 34}, {"i": 34, "sec": "第32章 RNA的生物合成和加工 · 中文PPT原图", "title": "七、转录作用的抑制剂", "notes": "College of Life Sciences, CNU\n七、转录作用的抑制剂\n1. 核苷酸合成抑制剂：\n ⚫ 嘌呤、嘧啶类似物\n ⚫ 氨基酸类似物\n\n ⚫ 叶酸类似物\n\n2. DNA模板功能的抑制剂\n ⚫ 放线菌素D\n 插入DNA双链碱基对之间\n ⚫ 嵌入染料(溴化乙锭)\n\n3. RNA聚合酶的抑制剂\n ⚫ 利福平 抑制细菌RNA聚合酶亚基\n ⚫ α-鹅膏蕈碱 抑制真核生物RNA聚合酶", "points": ["1. 核苷酸合成抑制剂：", "嘌呤、嘧啶类似物", "氨基酸类似物", "2. DNA模板功能的抑制剂"], "img": "assets/img/bc32ppt/s-35.jpg", "imageExplain": "中文PPT第35页；右侧为从PPT提取的文字，图片保留原始排版。", "fig": "中文PPT：RNA的生物合成和转录后加工.pdf", "page": 35}, {"i": 35, "sec": "第32章 RNA的生物合成和加工 · 中文PPT原图", "title": "第二节 RNA的转录后加工", "notes": "第二节 RNA的转录后加工", "points": [], "img": "assets/img/bc32ppt/s-36.jpg", "imageExplain": "中文PPT第36页；右侧为从PPT提取的文字，图片保留原始排版。", "fig": "中文PPT：RNA的生物合成和转录后加工.pdf", "page": 36}, {"i": 36, "sec": "第32章 RNA的生物合成和加工 · 中文PPT原图", "title": "转录后加工（post-transcriptional processing）过程：", "notes": "College of Life Sciences, CNU\n转录后加工（post-transcriptional processing）过程：\n\n • 切割（cutting）\n • 修剪（trimming）\n • 添加（appending）\n • 修饰（modification）和异构化（isomerization）\n • 拼接（splicing）\n • 编辑（editing）\n • 再编码（recoding）（校正tRNA）\n （校正tRNA）", "points": ["切割（cutting）", "修剪（trimming）", "添加（appending）", "修饰（modification）和异构化（isomerization）"], "img": "assets/img/bc32ppt/s-37.jpg", "imageExplain": "中文PPT第37页；右侧为从PPT提取的文字，图片保留原始排版。", "fig": "中文PPT：RNA的生物合成和转录后加工.pdf", "page": 37}, {"i": 37, "sec": "第32章 RNA的生物合成和加工 · 中文PPT原图", "title": "一、 rRNA前体加工", "notes": "College of Life Sciences, CNU\n一、 rRNA前体加工\n1. 原核生物rRNA前体的加工：\n\n rRNA的基因为多拷贝。rRNA的基因与某些tRNA的\n 基因组成一个转录单位。\n\n E. coli:\n 有7个rRNA的转录单位，每个转录单位由16S 、23S 、\n 5S rRNA基因与一个或几个tRNA的基因组成。\n\n❖加工过程：\n -甲基化：甲基化位置常在核糖2-OH上。\n -切割和修剪： 核酸酶", "points": ["1. 原核生物rRNA前体的加工：", "rRNA的基因为多拷贝。rRNA的基因与某些tRNA的", "基因组成一个转录单位。", "E. coli:"], "img": "assets/img/bc32ppt/s-38.jpg", "imageExplain": "中文PPT第38页；右侧为从PPT提取的文字，图片保留原始排版。", "fig": "中文PPT：RNA的生物合成和转录后加工.pdf", "page": 38}, {"i": 38, "sec": "第32章 RNA的生物合成和加工 · 中文PPT原图", "title": "细菌 rRNA前体 的加工", "notes": "College of Life Sciences, CNU\n 细菌 rRNA前体 的加工\n\n 1: RNase Ⅲ\n 2. RNase P\n 3. RNase E\n 甲基化\n~30个甲基化\n\n 切割\n\n 修剪", "points": ["1: RNase Ⅲ", "2. RNase P", "3. RNase E", "~30个甲基化"], "img": "assets/img/bc32ppt/s-39.jpg", "imageExplain": "中文PPT第39页；右侧为从PPT提取的文字，图片保留原始排版。", "fig": "中文PPT：RNA的生物合成和转录后加工.pdf", "page": 39}, {"i": 39, "sec": "第32章 RNA的生物合成和加工 · 中文PPT原图", "title": "2. 真核生物rRNA前体的加工", "notes": "College of Life Sciences, CNU\n2. 真核生物rRNA前体的加工\n\n rRNA基因拷贝数较多（几十~几千）。rRNA基因成\n 簇排列，由16~18 S、5.8S、26~28S rRNA基因组成一个转\n 录单位，彼此以间隔区分开。\n\n❖ 加工过程：\n\n ⚫ 与原核生物相似，但甲基化程度比原核生物高。\n ⚫ 甲基化、假尿苷化、切割由核仁小RNA (snoRNA)指导。", "points": ["rRNA基因拷贝数较多（几十~几千）。rRNA基因成", "簇排列，由16~18 S、5.8S、26~28S rRNA基因组成一个转", "录单位，彼此以间隔区分开。", "❖ 加工过程："], "img": "assets/img/bc32ppt/s-40.jpg", "imageExplain": "中文PPT第40页；右侧为从PPT提取的文字，图片保留原始排版。", "fig": "中文PPT：RNA的生物合成和转录后加工.pdf", "page": 40}, {"i": 40, "sec": "第32章 RNA的生物合成和加工 · 中文PPT原图", "title": "真核生物 rRNA前体 的加工", "notes": "College of Life Sciences, CNU\n 真核生物 rRNA前体 的加工\n\n＞100个甲基化", "points": ["＞100个甲基化"], "img": "assets/img/bc32ppt/s-41.jpg", "imageExplain": "中文PPT第41页；右侧为从PPT提取的文字，图片保留原始排版。", "fig": "中文PPT：RNA的生物合成和转录后加工.pdf", "page": 41}, {"i": 41, "sec": "第32章 RNA的生物合成和加工 · 中文PPT原图", "title": "二、 tRNA前体加工", "notes": "College of Life Sciences, CNU\n二、 tRNA前体加工\n\n 原核与真核生物tRNA基因是多拷贝的。不同种tRNA\n基因成簇排列，彼此以间隔区分开，组成一个转录单位。\n\n❖加工过程\n\n• 核酸内切酶在tRNA两端切断： RNase P, F\n• 核酸外切酶（RNase D）从3端逐个切去附加序列（修剪）\n• 在3端添加－CCAOH：tRNA核苷酰转移酶\n• 核苷酸的修饰和异构化： 修饰酶、异构化酶\n• 剪接：去除内含子（某些真核生物tRNA）", "points": ["原核与真核生物tRNA基因是多拷贝的。不同种tRNA", "基因成簇排列，彼此以间隔区分开，组成一个转录单位。", "核酸内切酶在tRNA两端切断： RNase P, F", "核酸外切酶（RNase D）从3端逐个切去附加序列（修剪）"], "img": "assets/img/bc32ppt/s-42.jpg", "imageExplain": "中文PPT第42页；右侧为从PPT提取的文字，图片保留原始排版。", "fig": "中文PPT：RNA的生物合成和转录后加工.pdf", "page": 42}, {"i": 42, "sec": "第32章 RNA的生物合成和加工 · 中文PPT原图", "title": "细菌和真核生物 tRNA前体 的加工", "notes": "College of Life Sciences, CNU\n 细菌和真核生物 tRNA前体 的加工\n\n 3 端成熟酶\n RNase F\n5\n端\n成\n熟\n酶\n\n ⚫ RNase P: 是一种核酸内切酶，由蛋白质和RNA（ M1RNA ）\n 组成。原核生物RNaseP的RNA（ 375nts）单独具有切割活性。\n ⚫真核生物tRNA3’端CCA是后加上去的。", "points": ["3 端成熟酶", "RNase F", "RNase P: 是一种核酸内切酶，由蛋白质和RNA（ M1RNA ）", "组成。原核生物RNaseP的RNA（ 375nts）单独具有切割活性。"], "img": "assets/img/bc32ppt/s-43.jpg", "imageExplain": "中文PPT第43页；右侧为从PPT提取的文字，图片保留原始排版。", "fig": "中文PPT：RNA的生物合成和转录后加工.pdf", "page": 43}, {"i": 43, "sec": "第32章 RNA的生物合成和加工 · 中文PPT原图", "title": "RNase P的RNA（M1RNA）", "notes": "College of Life Sciences, CNU\n\nRNase P的RNA（M1RNA）\n具有催化活性。\n\n四膜虫rRNA前体的自我拼接，\n发现RNA具催化功能。\n（L19RNA —395个核苷酸\n构成的线状RNA分子）", "points": ["具有催化活性。", "四膜虫rRNA前体的自我拼接，", "发现RNA具催化功能。", "（L19RNA —395个核苷酸"], "img": "assets/img/bc32ppt/s-44.jpg", "imageExplain": "中文PPT第44页；右侧为从PPT提取的文字，图片保留原始排版。", "fig": "中文PPT：RNA的生物合成和转录后加工.pdf", "page": 44}, {"i": 44, "sec": "第32章 RNA的生物合成和加工 · 中文PPT原图", "title": "tRNA分子中被修饰的碱基", "notes": "College of Life Sciences, CNU\ntRNA分子中被修饰的碱基", "points": [], "img": "assets/img/bc32ppt/s-45.jpg", "imageExplain": "中文PPT第45页；右侧为从PPT提取的文字，图片保留原始排版。", "fig": "中文PPT：RNA的生物合成和转录后加工.pdf", "page": 45}, {"i": 45, "sec": "第32章 RNA的生物合成和加工 · 中文PPT原图", "title": "三、mRNA前体的加工", "notes": "College of Life Sciences, CNU\n三、mRNA前体的加工\n⚫ 原核生物\n mRNA一般不需要加工，仅有少数需要简单加工。\n 例如，某种蓝细菌DNA聚合酶III\n 的亚基具有4个内含子\n\n⚫ 真核生物\n mRNA前体为核内不均一RNA（hnRNA）。\n\n❖加工包括：\n - 5端加帽（m7G 5ppp5 NmpNp- ）\n - 3加poly A尾巴\n - 拼接\n - 核苷酸甲基化：例如，6N-甲基腺嘌呤 (m6A)", "points": ["mRNA一般不需要加工，仅有少数需要简单加工。", "例如，某种蓝细菌DNA聚合酶III", "的亚基具有4个内含子", "mRNA前体为核内不均一RNA（hnRNA）。"], "img": "assets/img/bc32ppt/s-46.jpg", "imageExplain": "中文PPT第46页；右侧为从PPT提取的文字，图片保留原始排版。", "fig": "中文PPT：RNA的生物合成和转录后加工.pdf", "page": 46}, {"i": 46, "sec": "第32章 RNA的生物合成和加工 · 中文PPT原图", "title": "真核生物 mRNA前体（hnRNA）的加工", "notes": "College of Life Sciences, CNU\n真核生物 mRNA前体（hnRNA）的加工", "points": [], "img": "assets/img/bc32ppt/s-47.jpg", "imageExplain": "中文PPT第47页；右侧为从PPT提取的文字，图片保留原始排版。", "fig": "中文PPT：RNA的生物合成和转录后加工.pdf", "page": 47}, {"i": 47, "sec": "第32章 RNA的生物合成和加工 · 中文PPT原图", "title": "1. mRNA前体的加帽", "notes": "College of Life Sciences, CNU\n 1. mRNA前体的加帽\n Cap0 型\n m7G 5ppp5 Np\n\n 磷酸酶\n\n 鸟苷酰转移酶\n\n S-腺苷Met\n CapI 型\n m7G 5ppp5 NmpNp- 甲基转移酶 S-腺苷高Cys\n （大多数真核生物）\n\nCapII 型 甲基转移酶\nm7G 5ppp5 N1mpN2mp-", "points": ["Cap0 型", "m7G 5ppp5 Np", "鸟苷酰转移酶", "S-腺苷Met"], "img": "assets/img/bc32ppt/s-48.jpg", "imageExplain": "中文PPT第48页；右侧为从PPT提取的文字，图片保留原始排版。", "fig": "中文PPT：RNA的生物合成和转录后加工.pdf", "page": 48}, {"i": 48, "sec": "第32章 RNA的生物合成和加工 · 中文PPT原图", "title": "2. mRNA前体的加尾", "notes": "College of Life Sciences, CNU\n2. mRNA前体的加尾\n\n在加尾信号AAUAAA 3’端\n11 ~30 核苷酸处切断mRNA，\n并在后面聚合 含有20 ~ 200\n腺苷酸的poly(A)尾巴。\n\n 加尾信号\n\n酶复合物：包括特异因子、\n 内切酶\n剪切因子, PolyA聚合酶等\n\n注：组蛋白mRNA等没有\n PolyA聚合酶\npoly(A）尾", "points": ["在加尾信号AAUAAA 3’端", "11 ~30 核苷酸处切断mRNA，", "并在后面聚合 含有20 ~ 200", "腺苷酸的poly(A)尾巴。"], "img": "assets/img/bc32ppt/s-49.jpg", "imageExplain": "中文PPT第49页；右侧为从PPT提取的文字，图片保留原始排版。", "fig": "中文PPT：RNA的生物合成和转录后加工.pdf", "page": 49}, {"i": 49, "sec": "第32章 RNA的生物合成和加工 · 中文PPT原图", "title": "3. RNA的拼接（splicing）", "notes": "College of Life Sciences, CNU\n3. RNA的拼接（splicing）\n\n 真核生物断裂基因转录物的加工中，去除内含\n 子，使外显子成为连续序列，这一过程称为拼接。\n\n 四种方式：\n 类型I自我拼接\n 类型II自我拼接\n 真核mRNA的拼接体的拼接\n 核tRNA的酶促拼接（自学）", "points": ["真核生物断裂基因转录物的加工中，去除内含", "子，使外显子成为连续序列，这一过程称为拼接。", "类型I自我拼接", "类型II自我拼接"], "img": "assets/img/bc32ppt/s-50.jpg", "imageExplain": "中文PPT第50页；右侧为从PPT提取的文字，图片保留原始排版。", "fig": "中文PPT：RNA的生物合成和转录后加工.pdf", "page": 50}, {"i": 50, "sec": "第32章 RNA的生物合成和加工 · 中文PPT原图", "title": "类型I自我拼接", "notes": "College of Life Sciences, CNU\n类型I自我拼接\n低等真核生物核rRNA基因\n真核生物细胞器基因\n细菌和噬菌体的个别基因\n\n 鸟苷（鸟苷酸） 第一次转酯反应\n\n外显子\n 鸟苷\n\n 第二次转酯反应\n\n 内含子", "points": ["低等真核生物核rRNA基因", "真核生物细胞器基因", "细菌和噬菌体的个别基因", "鸟苷（鸟苷酸） 第一次转酯反应"], "img": "assets/img/bc32ppt/s-51.jpg", "imageExplain": "中文PPT第51页；右侧为从PPT提取的文字，图片保留原始排版。", "fig": "中文PPT：RNA的生物合成和转录后加工.pdf", "page": 51}, {"i": 51, "sec": "第32章 RNA的生物合成和加工 · 中文PPT原图", "title": "类型Ⅱ自我拼接", "notes": "College of Life Sciences, CNU\n类型Ⅱ自我拼接\n\n某些真菌线粒体基因\n植物叶绿体基因\n\n 套索", "points": ["某些真菌线粒体基因", "植物叶绿体基因"], "img": "assets/img/bc32ppt/s-52.jpg", "imageExplain": "中文PPT第52页；右侧为从PPT提取的文字，图片保留原始排版。", "fig": "中文PPT：RNA的生物合成和转录后加工.pdf", "page": 52}, {"i": 52, "sec": "第32章 RNA的生物合成和加工 · 中文PPT原图", "title": "真核生物hnRNA拼接 (拼接体的拼接)", "notes": "College of Life Sciences, CNU\n真核生物hnRNA拼接 (拼接体的拼接)\n\n⚫ GU-AG规则：真核生物mRNA前体的内含子\n 5端为GU, 3端为AG。\n\n例：一些生物体mRNA前体拼接点的序列", "points": ["GU-AG规则：真核生物mRNA前体的内含子", "5端为GU, 3端为AG。", "例：一些生物体mRNA前体拼接点的序列"], "img": "assets/img/bc32ppt/s-53.jpg", "imageExplain": "中文PPT第53页；右侧为从PPT提取的文字，图片保留原始排版。", "fig": "中文PPT：RNA的生物合成和转录后加工.pdf", "page": 53}, {"i": 53, "sec": "第32章 RNA的生物合成和加工 · 中文PPT原图", "title": "核内小RNA（SnRNA）U系列 （富含尿嘧啶）", "notes": "College of Life Sciences, CNU\n⚫ 核内小RNA（SnRNA）U系列 （富含尿嘧啶）\n\nSnRNA （U1、U2、U4、U5、U6）一般长约100-300\n核苷酸，含有与内含子互补的碱基顺序。当snRNA\n和内含子的未端碱基配对后，可使外显子正确并列，\n有利于外显子的拼接和内含子的去除。\n\nSnRNA 可与蛋白质结合形成核糖核蛋白（SnRNP）。\n\n (注：U3参与rRNA前体的加工)", "points": ["SnRNA （U1、U2、U4、U5、U6）一般长约100-300", "核苷酸，含有与内含子互补的碱基顺序。当snRNA", "和内含子的未端碱基配对后，可使外显子正确并列，", "有利于外显子的拼接和内含子的去除。"], "img": "assets/img/bc32ppt/s-54.jpg", "imageExplain": "中文PPT第54页；右侧为从PPT提取的文字，图片保留原始排版。", "fig": "中文PPT：RNA的生物合成和转录后加工.pdf", "page": 54}, {"i": 54, "sec": "第32章 RNA的生物合成和加工 · 中文PPT原图", "title": "拼接体（spliceosome）", "notes": "College of Life Sciences, CNU\n⚫拼接体（spliceosome）\n\n在被拼接的hnRNA\n上U1、U2、U4-6和\n约50种蛋白质所组成\n的复合物。\n\n Structure of the human spliceosome,\n determined by cryo-EM.", "points": ["在被拼接的hnRNA", "上U1、U2、U4-6和", "约50种蛋白质所组成", "Structure of the human spliceosome,"], "img": "assets/img/bc32ppt/s-55.jpg", "imageExplain": "中文PPT第55页；右侧为从PPT提取的文字，图片保留原始排版。", "fig": "中文PPT：RNA的生物合成和转录后加工.pdf", "page": 55}, {"i": 55, "sec": "第32章 RNA的生物合成和加工 · 中文PPT原图", "title": "分支点序列", "notes": "College of Life Sciences, CNU\n⚫分支点序列\n\n UACUAAC， 十分保守，其中未配对A的2OH可\n 以亲核攻击5 拼接点。", "points": ["UACUAAC， 十分保守，其中未配对A的2OH可", "以亲核攻击5 拼接点。"], "img": "assets/img/bc32ppt/s-56.jpg", "imageExplain": "中文PPT第56页；右侧为从PPT提取的文字，图片保留原始排版。", "fig": "中文PPT：RNA的生物合成和转录后加工.pdf", "page": 56}, {"i": 56, "sec": "第32章 RNA的生物合成和加工 · 中文PPT原图", "title": "真核生物mRNA前体的拼接位点", "notes": "College of Life Sciences, CNU\n⚫ 真核生物mRNA前体的拼接位点\n （显示出内含子和外显子交界处的保守序列）\n\n 分支点\n\n 分支点序列（UACUAAC）距内含子3端20-50个碱基，当\nU2 与分支点配对后，分支点内有一个A没有配对，突出在双\n链外被激活，其2OH亲核攻击5 拼接点，为第一次转酯反应\n创造了条件。", "points": ["（显示出内含子和外显子交界处的保守序列）", "分支点序列（UACUAAC）距内含子3端20-50个碱基，当", "U2 与分支点配对后，分支点内有一个A没有配对，突出在双", "链外被激活，其2OH亲核攻击5 拼接点，为第一次转酯反应"], "img": "assets/img/bc32ppt/s-57.jpg", "imageExplain": "中文PPT第57页；右侧为从PPT提取的文字，图片保留原始排版。", "fig": "中文PPT：RNA的生物合成和转录后加工.pdf", "page": 57}, {"i": 57, "sec": "第32章 RNA的生物合成和加工 · 中文PPT原图", "title": "mRNA前体的拼接机制", "notes": "College of Life Sciences, CNU\n⚫ mRNA前体的拼接机制\n\n U1 snRNP结合在5端拼接点\n\n U2 snRNP结合在分支点\n\n U4/U6和U5 snRNP三聚体进\n 入拼接体", "points": ["U1 snRNP结合在5端拼接点", "U2 snRNP结合在分支点", "U4/U6和U5 snRNP三聚体进"], "img": "assets/img/bc32ppt/s-58.jpg", "imageExplain": "中文PPT第58页；右侧为从PPT提取的文字，图片保留原始排版。", "fig": "中文PPT：RNA的生物合成和转录后加工.pdf", "page": 58}, {"i": 58, "sec": "第32章 RNA的生物合成和加工 · 中文PPT原图", "title": "U1 、U4被释放；U6结合在5拼接", "notes": "College of Life Sciences, CNU\n\nU1 、U4被释放；U6结合在5拼接\n点；U6与 U2结合，将分支点上突\n出的A 2OH 拉近到5拼接点 。\n\n分支点 A 2OH 对5 拼接点处的磷\n酸二酯键进行攻击, 5拼接点断开,\n形成套索, 释放出5 拼接点3OH，\n完成第一次转酯反应。\n\nU5使5 和3 外显子靠近，5 拼接点\n3OH 攻击3拼接点的磷酸二酯键，\n完成第二次转酯反应；\n\n3拼接点断开, 外显子拼接, 套索结\n构释放 。", "points": ["点；U6与 U2结合，将分支点上突", "出的A 2OH 拉近到5拼接点 。", "分支点 A 2OH 对5 拼接点处的磷", "酸二酯键进行攻击, 5拼接点断开,"], "img": "assets/img/bc32ppt/s-59.jpg", "imageExplain": "中文PPT第59页；右侧为从PPT提取的文字，图片保留原始排版。", "fig": "中文PPT：RNA的生物合成和转录后加工.pdf", "page": 59}, {"i": 59, "sec": "第32章 RNA的生物合成和加工 · 中文PPT原图", "title": "卵清蛋白基因 mRNA前体的加工", "notes": "College of Life Sciences, CNU\n卵清蛋白基因 mRNA前体的加工\n\n 卵清蛋白基因", "points": ["卵清蛋白基因"], "img": "assets/img/bc32ppt/s-60.jpg", "imageExplain": "中文PPT第60页；右侧为从PPT提取的文字，图片保留原始排版。", "fig": "中文PPT：RNA的生物合成和转录后加工.pdf", "page": 60}, {"i": 60, "sec": "第32章 RNA的生物合成和加工 · 中文PPT原图", "title": "选择性拼接（alternative splicing ）", "notes": "College of Life Sciences, CNU\n⚫ 选择性拼接（alternative splicing ）\n\n 一个基因的转录产物在不同的细胞、发育阶段\n 和生理状态下，通过不同的拼接方式，可以得到\n 不同的mRNA和翻译产物，称为选择性拼接。", "points": ["一个基因的转录产物在不同的细胞、发育阶段", "和生理状态下，通过不同的拼接方式，可以得到", "不同的mRNA和翻译产物，称为选择性拼接。"], "img": "assets/img/bc32ppt/s-61.jpg", "imageExplain": "中文PPT第61页；右侧为从PPT提取的文字，图片保留原始排版。", "fig": "中文PPT：RNA的生物合成和转录后加工.pdf", "page": 61}, {"i": 61, "sec": "第32章 RNA的生物合成和加工 · 中文PPT原图", "title": "鼠降钙素（ calcitonin ）mRNA前体的选择性加工", "notes": "College of Life Sciences, CNU\n鼠降钙素（ calcitonin ）mRNA前体的选择性加工\n\n mRNA前体有两个\n polyA位点\n\n甲状腺 脑\n\n 降钙素 降钙素基因相关肽", "points": ["mRNA前体有两个", "polyA位点", "降钙素 降钙素基因相关肽"], "img": "assets/img/bc32ppt/s-62.jpg", "imageExplain": "中文PPT第62页；右侧为从PPT提取的文字，图片保留原始排版。", "fig": "中文PPT：RNA的生物合成和转录后加工.pdf", "page": 62}, {"i": 62, "sec": "第32章 RNA的生物合成和加工 · 中文PPT原图", "title": "RNA拼接的生物学意义", "notes": "College of Life Sciences, CNU\n ⚫ RNA拼接的生物学意义\n（1）RNA拼接是进化的结果 基序：超二级结构\n 基因由模块（外显子）装配而成，模块间序列演变为内\n 含子，基因外显子与蛋白质的结构域、亚结构域、基序\n （motif）相对应。\n\n（2）RNA拼接是基因表达调节的重要环节\n 通过选择性拼接，抽取有用信息，形成连续的编码序列，\n 控制机体生长发育。\n\n（3）内含子的存在和拼接对于生物机体的进化十分重要\n • 遗传重组可发生在内含子处，避免了基因错位导致的失活\n • 内含子增加了基因组的复杂性，可成为新的编码序列", "points": ["（1）RNA拼接是进化的结果 基序：超二级结构", "基因由模块（外显子）装配而成，模块间序列演变为内", "含子，基因外显子与蛋白质的结构域、亚结构域、基序", "（motif）相对应。"], "img": "assets/img/bc32ppt/s-63.jpg", "imageExplain": "中文PPT第63页；右侧为从PPT提取的文字，图片保留原始排版。", "fig": "中文PPT：RNA的生物合成和转录后加工.pdf", "page": 63}, {"i": 63, "sec": "第32章 RNA的生物合成和加工 · 中文PPT原图", "title": "四、RNA的编辑(editing)", "notes": "College of Life Sciences, CNU\n四、RNA的编辑(editing)\n 改变RNA的编码序列。\n1. RNA编辑的不同类型和分布\n\n 编辑类型 机制 存在\nU的插入与删除 guide RNA指导的反应 锥虫线粒体mRNA\nC、A或U的插入 多头绒胞菌线粒体mRNA和rRNA\nG的插入 RNA聚合酶重复转录 副粘病毒的P基因\nC 转变为U 酶促脱氨 哺乳类肠的apoB mRNA\nC转变为U或U转变为C 脱氨或氨基化 植物线粒体mRNA和rRNA\n 牛心线粒体RNA\nA转变为I 脱氨 脑谷氨酸受体亚基mRNA", "points": ["改变RNA的编码序列。", "1. RNA编辑的不同类型和分布", "编辑类型 机制 存在", "U的插入与删除 guide RNA指导的反应 锥虫线粒体mRNA"], "img": "assets/img/bc32ppt/s-64.jpg", "imageExplain": "中文PPT第64页；右侧为从PPT提取的文字，图片保留原始排版。", "fig": "中文PPT：RNA的生物合成和转录后加工.pdf", "page": 64}, {"i": 64, "sec": "第32章 RNA的生物合成和加工 · 中文PPT原图", "title": "锥虫线粒体细胞色素氧化酶亚基II mRNA的编辑", "notes": "College of Life Sciences, CNU\n 锥虫线粒体细胞色素氧化酶亚基II mRNA的编辑\n\n锥虫线粒体细胞色素氧化酶基因与人 和酵母相应基因相比，\n存在-1移码突变，但在mRNA中移码位点附近插入4个额外的U。\n\n 60nts\n\n 20S复合体：\n 核酸内切酶\n 末端尿苷酰转移酶\n RNA连接酶\n\n （p502）\n （p502）", "points": ["锥虫线粒体细胞色素氧化酶基因与人 和酵母相应基因相比，", "存在-1移码突变，但在mRNA中移码位点附近插入4个额外的U。", "20S复合体：", "末端尿苷酰转移酶"], "img": "assets/img/bc32ppt/s-65.jpg", "imageExplain": "中文PPT第65页；右侧为从PPT提取的文字，图片保留原始排版。", "fig": "中文PPT：RNA的生物合成和转录后加工.pdf", "page": 65}, {"i": 65, "sec": "第32章 RNA的生物合成和加工 · 中文PPT原图", "title": "低密度脂蛋白的载脂蛋白apoB-100 基因的RNA 编辑", "notes": "College of Life Sciences, CNU\n低密度脂蛋白的载脂蛋白apoB-100 基因的RNA 编辑\n\n 肝\n\n小肠\n\nC→U, 使得CAA →UAA (终止密码)，肽链合成提前结束。", "points": ["C→U, 使得CAA →UAA (终止密码)，肽链合成提前结束。"], "img": "assets/img/bc32ppt/s-66.jpg", "imageExplain": "中文PPT第66页；右侧为从PPT提取的文字，图片保留原始排版。", "fig": "中文PPT：RNA的生物合成和转录后加工.pdf", "page": 66}, {"i": 66, "sec": "第32章 RNA的生物合成和加工 · 中文PPT原图", "title": "2. RNA编辑的意义", "notes": "College of Life Sciences, CNU\n2. RNA编辑的意义\n\n ⚫ 消除移码突变的危害\n\n ⚫ 增加了基因产物的多样性\n\n ⚫ 使基因产物获得新的结构和功能\n\n ⚫ 是基因调控的重要方式", "points": ["消除移码突变的危害", "增加了基因产物的多样性", "使基因产物获得新的结构和功能", "是基因调控的重要方式"], "img": "assets/img/bc32ppt/s-67.jpg", "imageExplain": "中文PPT第67页；右侧为从PPT提取的文字，图片保留原始排版。", "fig": "中文PPT：RNA的生物合成和转录后加工.pdf", "page": 67}, {"i": 67, "sec": "第32章 RNA的生物合成和加工 · 中文PPT原图", "title": "五、RNA生物功能的多样性", "notes": "College of Life Sciences, CNU\n五、RNA生物功能的多样性\n1. 在遗传信息的翻译中起决定性作用\n mRNA, rRNA, tRNA\n\n2. 具有重要的催化功能\n ⚫ 端粒酶 （逆转录酶 活性 ）\n ⚫ RNaseP(M1RNA) （参与tRNA的加工）\n ⚫ L19RNA （参与四膜虫rRNA前体的拼接）\n\n3. 转录后加工和修饰依赖于各种小RNA和其蛋白质复合物\n ⚫ 核仁小RNA (snoRNA) （参与rRNA的加工）\n ⚫ 核内小RNA（SnRNA）U系列 （参与hnRNA 的加工）", "points": ["1. 在遗传信息的翻译中起决定性作用", "mRNA, rRNA, tRNA", "2. 具有重要的催化功能", "端粒酶 （逆转录酶 活性 ）"], "img": "assets/img/bc32ppt/s-68.jpg", "imageExplain": "中文PPT第68页；右侧为从PPT提取的文字，图片保留原始排版。", "fig": "中文PPT：RNA的生物合成和转录后加工.pdf", "page": 68}, {"i": 68, "sec": "第32章 RNA的生物合成和加工 · 中文PPT原图", "title": "4. 对基因表达和细胞功能具有重要调节作用", "notes": "College of Life Sciences, CNU\n\n4. 对基因表达和细胞功能具有重要调节作用\n\n⚫ RNA干扰（RNA interference, RNAi）与基因沉默\n\n➢ 基因沉默，包括 转录前水平的基因沉默和转录后水平的基\n 因沉默 。前者包括 由于 DNA修饰或染色体异染色质化等\n 导致 的基因沉默。后者 指 转录 后靶mRNA序列被 特异性\n 降解或 抑制翻译 。\n\n➢ RNA干扰是指由双链RNA（double-stranded RNA，\n dsRNA）诱发的、导致 同源mRNA特异性降解或翻译受到\n 抑制的 现象 。\n\n 在高等真核生物中已鉴定出上千种microRNAs，可能影\n 响三分之一哺乳动物基因的表达。", "points": ["RNA干扰（RNA interference, RNAi）与基因沉默", "➢ 基因沉默，包括 转录前水平的基因沉默和转录后水平的基", "因沉默 。前者包括 由于 DNA修饰或染色体异染色质化等", "导致 的基因沉默。后者 指 转录 后靶mRNA序列被 特异性"], "img": "assets/img/bc32ppt/s-69.jpg", "imageExplain": "中文PPT第69页；右侧为从PPT提取的文字，图片保留原始排版。", "fig": "中文PPT：RNA的生物合成和转录后加工.pdf", "page": 69}, {"i": 69, "sec": "第32章 RNA的生物合成和加工 · 中文PPT原图", "title": "RNA干扰导致的基因沉默", "notes": "College of Life Sciences, CNU\n RNA干扰导致的基因沉默\n 发育阶段 内源 外源\nmicroRNA前体\n(70~90核苷酸)\n RNA内切酶\n\nSmall temporal RNA Small interfering RNA\n (小干扰RNA)\n （~23核苷酸） RNA解旋酶\n\nmicroRNA, miRNA RNA诱导的沉默复合物\n（微RNA）\n （反义RNA） （RISC）\n -链\n 反义RNA\n RNA酶\n RNA解旋酶\n一般结合在3-UTR Ago蛋白\n (p229)\n\n 诱导靶基因启动子处\n 染色质修饰，导致基 降解 翻译抑制\n 因沉默 (p571)", "points": ["发育阶段 内源 外源", "microRNA前体", "(70~90核苷酸)", "RNA内切酶"], "img": "assets/img/bc32ppt/s-70.jpg", "imageExplain": "中文PPT第70页；右侧为从PPT提取的文字，图片保留原始排版。", "fig": "中文PPT：RNA的生物合成和转录后加工.pdf", "page": 70}, {"i": 70, "sec": "第32章 RNA的生物合成和加工 · 中文PPT原图", "title": "The Nobel Prize in Physiology or Medicine 2006 College of Life…", "notes": "The Nobel Prize in Physiology or Medicine 2006 College of Life Sciences, CNU\n\n “for their discovery of RNA interference-gene silencing\n by double-strand RNA”\n\n Andrew Z. Fire Craig C. Mello\n （1959-） Stanford University （1960-）University of\n School of Medicine, Stanford, Massachusetts Medical School,\n CA, USA Worcester, MA, USA", "points": ["The Nobel Prize in Physiology or Medicine 2006 College of Life Sciences, CNU", "“for their discovery of RNA interference-gene silencing", "by double-strand RNA”", "Andrew Z. Fire Craig C. Mello"], "img": "assets/img/bc32ppt/s-71.jpg", "imageExplain": "中文PPT第71页；右侧为从PPT提取的文字，图片保留原始排版。", "fig": "中文PPT：RNA的生物合成和转录后加工.pdf", "page": 71}, {"i": 71, "sec": "第32章 RNA的生物合成和加工 · 中文PPT原图", "title": "5. 在生物的进化中起重要作用", "notes": "College of Life Sciences, CNU\n\n5. 在生物的进化中起重要作用\n\n 例如，RNA的拼接和编辑可以增加遗传信息的多样性、\n消除基因突变的危害，促进生物进化。", "points": ["例如，RNA的拼接和编辑可以增加遗传信息的多样性、", "消除基因突变的危害，促进生物进化。"], "img": "assets/img/bc32ppt/s-72.jpg", "imageExplain": "中文PPT第72页；右侧为从PPT提取的文字，图片保留原始排版。", "fig": "中文PPT：RNA的生物合成和转录后加工.pdf", "page": 72}, {"i": 72, "sec": "第32章 RNA的生物合成和加工 · 中文PPT原图", "title": "第三节 RNA的复制", "notes": "第三节 RNA的复制", "points": [], "img": "assets/img/bc32ppt/s-73.jpg", "imageExplain": "中文PPT第73页；右侧为从PPT提取的文字，图片保留原始排版。", "fig": "中文PPT：RNA的生物合成和转录后加工.pdf", "page": 73}, {"i": 73, "sec": "第32章 RNA的生物合成和加工 · 中文PPT原图", "title": "RNA的复制", "notes": "• RNA的复制\n RNA指导下RNA的合成。\n\n• RNA复制酶\n - 以RNA为模板\n - 以4种NTP为底物\n - 聚合方向5→3", "points": ["RNA指导下RNA的合成。", "RNA复制酶", "以RNA为模板", "以4种NTP为底物"], "img": "assets/img/bc32ppt/s-74.jpg", "imageExplain": "中文PPT第74页；右侧为从PPT提取的文字，图片保留原始排版。", "fig": "中文PPT：RNA的生物合成和转录后加工.pdf", "page": 74}, {"i": 74, "sec": "第32章 RNA的生物合成和加工 · 中文PPT原图", "title": "一、噬菌体QRNA的复制", "notes": "College of Life Sciences, CNU\n一、噬菌体QRNA的复制\n\n 噬菌体Q 是直径20nm的正二十面体小噬菌体。\n\n 1条RNA单链（+链）： 4500核苷酸\n 基因次序为：\n 5- 成熟蛋白-外壳蛋白（或A1蛋白）-复制酶亚基 -3\n\n 蛋白质\n\n  亚基（催化中心）\n （核糖体蛋白S1）\n 复制酶\n （4个亚基） （肽链延长因子EF-Tu） 宿主细胞\n （肽链延长因子EF-Ts）", "points": ["噬菌体Q 是直径20nm的正二十面体小噬菌体。", "1条RNA单链（+链）： 4500核苷酸", "基因次序为：", "5- 成熟蛋白-外壳蛋白（或A1蛋白）-复制酶亚基 -3"], "img": "assets/img/bc32ppt/s-75.jpg", "imageExplain": "中文PPT第75页；右侧为从PPT提取的文字，图片保留原始排版。", "fig": "中文PPT：RNA的生物合成和转录后加工.pdf", "page": 75}, {"i": 75, "sec": "第32章 RNA的生物合成和加工 · 中文PPT原图", "title": "QRNA的复制过程", "notes": "College of Life Sciences, CNU\nQRNA的复制过程\n\n1. 复制酶的组装：\n + +\n 侵染 翻译 病毒颗粒蛋白\n E. coli 细胞\nRNA mRNA 复制酶亚基\n 复制酶\n 宿主、、\n2. 复制：\n + + - - -+ +\n 复制酶 释放 复制酶 释放\n\n RNA 中间体 RNA 中间体 RNA", "points": ["1. 复制酶的组装：", "侵染 翻译 病毒颗粒蛋白", "E. coli 细胞", "RNA mRNA 复制酶亚基"], "img": "assets/img/bc32ppt/s-76.jpg", "imageExplain": "中文PPT第76页；右侧为从PPT提取的文字，图片保留原始排版。", "fig": "中文PPT：RNA的生物合成和转录后加工.pdf", "page": 76}, {"i": 76, "sec": "第32章 RNA的生物合成和加工 · 中文PPT原图", "title": "二、病毒RNA复制的主要方式", "notes": "二、病毒RNA复制的主要方式\n\n1. 病毒RNA直接作为复制的模板：RNA→RNA\n “＋” RNA: Qβ、脊髓灰质炎病毒、SARS病毒、\n 新冠病毒\n “－”RNA：狂犬病病毒\n “±” RNA： 呼肠狐病毒\n\n2. RNA → DNA → RNA （逆转录作用）\n\n“+ +”： 逆转录病毒（致癌RNA病毒）", "points": ["1. 病毒RNA直接作为复制的模板：RNA→RNA", "“＋” RNA: Qβ、脊髓灰质炎病毒、SARS病毒、", "“－”RNA：狂犬病病毒", "“±” RNA： 呼肠狐病毒"], "img": "assets/img/bc32ppt/s-77.jpg", "imageExplain": "中文PPT第77页；右侧为从PPT提取的文字，图片保留原始排版。", "fig": "中文PPT：RNA的生物合成和转录后加工.pdf", "page": 77}, {"i": 77, "sec": "第32章 RNA的生物合成和加工 · 中文PPT原图", "title": "+ + 病毒颗粒蛋白 病", "notes": "College of Life Sciences, CNU\n\n - -+ + 病毒颗粒蛋白 病\n 复制酶 释放 毒\n + - -\n 颗\nRNA 中间体 RNA 释放 粒\n\n 中间体 RNA\n\n -+ + 病毒颗粒蛋白\n 复制酶 病\n 不对称复制 + - 毒\n 颗\nRNA RNA\n 粒\n RNA", "points": ["复制酶 释放 毒", "RNA 中间体 RNA 释放 粒", "中间体 RNA", "+ + 病毒颗粒蛋白"], "img": "assets/img/bc32ppt/s-78.jpg", "imageExplain": "中文PPT第78页；右侧为从PPT提取的文字，图片保留原始排版。", "fig": "中文PPT：RNA的生物合成和转录后加工.pdf", "page": 78}, {"i": 78, "sec": "第32章 RNA的生物合成和加工 · 中文PPT原图", "title": "SARS （Severe Acute Respiratory Syndrome）病毒", "notes": "SARS （Severe Acute Respiratory Syndrome）病毒\n 单链（+）RNA\n RNA: 29724 核苷酸\n\n核衣壳蛋白 5’端有甲基化“帽\n 子”，3’端有PolyA\n “尾巴”，与真核\n mRNA非常相似。\n\n RNA之间重组率\n 非常高，病毒出现\n 变异正是由于这种\n 小包膜糖蛋白 高重组率。\n刺突糖蛋白（S） 膜糖蛋白（M） （E）", "points": ["单链（+）RNA", "RNA: 29724 核苷酸", "核衣壳蛋白 5’端有甲基化“帽", "子”，3’端有PolyA"], "img": "assets/img/bc32ppt/s-79.jpg", "imageExplain": "中文PPT第79页；右侧为从PPT提取的文字，图片保留原始排版。", "fig": "中文PPT：RNA的生物合成和转录后加工.pdf", "page": 79}, {"i": 79, "sec": "第32章 RNA的生物合成和加工 · 中文PPT原图", "title": "新型冠状病毒(2019 novel coronavirus，2019-nCoV)", "notes": "新型冠状病毒(2019 novel coronavirus，2019-nCoV)\n\n 从武汉重症肺炎患者分离的病毒进行\n 电子显微镜形态学观察，结合病毒特\n 异性核苷酸检测和蛋白血清转化分析，\n 发现SARS-CoV-2 是主要病原体。\n (79. 5%相似性)\n\n病毒颗粒呈圆形或椭圆 病毒分类学:\n形，直径约60-140nm\n 冠状病毒科( Coronaviridae)\n 冠状病毒属( Coronavirus)\n β 类型冠状病毒（传染哺乳动物）", "points": ["从武汉重症肺炎患者分离的病毒进行", "电子显微镜形态学观察，结合病毒特", "异性核苷酸检测和蛋白血清转化分析，", "发现SARS-CoV-2 是主要病原体。"], "img": "assets/img/bc32ppt/s-80.jpg", "imageExplain": "中文PPT第80页；右侧为从PPT提取的文字，图片保留原始排版。", "fig": "中文PPT：RNA的生物合成和转录后加工.pdf", "page": 80}, {"i": 80, "sec": "第32章 RNA的生物合成和加工 · 中文PPT原图", "title": "新型冠状病毒的结构", "notes": "新型冠状病毒的结构\n\n 基因组(gRNA)：\n\n 1条正链RNA（+ssRNA）\n\n 含有29891 个核苷酸\n 编码9860 个氨基酸\n\n E 包膜蛋白(Envelope protein)\n 结构蛋白\n （4个） M 膜蛋白(Matrix protein)\n N 核衣壳蛋白(Nulceocapsid phosphorprotein)\n(参与病毒颗粒\n 组装) S 刺突蛋白(Spike glycoprotein)", "points": ["基因组(gRNA)：", "1条正链RNA（+ssRNA）", "含有29891 个核苷酸", "编码9860 个氨基酸"], "img": "assets/img/bc32ppt/s-81.jpg", "imageExplain": "中文PPT第81页；右侧为从PPT提取的文字，图片保留原始排版。", "fig": "中文PPT：RNA的生物合成和转录后加工.pdf", "page": 81}, {"i": 81, "sec": "第32章 RNA的生物合成和加工 · 中文PPT原图", "title": "新型冠状病毒的结构", "notes": "新型冠状病毒的结构\n 包膜蛋白\n （E）\n 膜蛋白 非结构蛋白(Nsp1-16)\n （M）\n (参与病毒复制)\n\n 例如：\n\n 单链RNA Nsp1：参与RNA加工\n (+ss RNA)\n Nsp3：蛋白酶\n (多肽链的加工)\n Nsp5：蛋白酶\n 核蛋白\n （N）\n Nap12：RNA 依赖的RNA\n 聚合酶(RdRp)\n Nsp13：解旋酶\n\n 刺突蛋白\n （S）\n 血管紧张素转化酶 2\n (ACE-2)", "points": ["膜蛋白 非结构蛋白(Nsp1-16)", "(参与病毒复制)", "单链RNA Nsp1：参与RNA加工", "(+ss RNA)"], "img": "assets/img/bc32ppt/s-82.jpg", "imageExplain": "中文PPT第82页；右侧为从PPT提取的文字，图片保留原始排版。", "fig": "中文PPT：RNA的生物合成和转录后加工.pdf", "page": 82}, {"i": 82, "sec": "第32章 RNA的生物合成和加工 · 中文PPT原图", "title": "新冠病毒的感染与复制模式图", "notes": "新冠病毒的感染与复制模式图\n 包括病毒吸附、入侵、遗传物质释放、基因组\nS 蛋白与细胞表\n面受体ACE2结合 转录和复制、组装和出芽等过程。\n\n吸附与侵入\n\n 跨膜丝氨酸蛋白酶2\n\n 膜融合 病毒释放\n RNA释放\n\n 翻译 S, M 和E蛋白在内质网翻译,\n N 蛋白在核糖体翻译\n以基因组RNA 转录\n为模板进行翻 翻译\n译，产生多聚\n 蛋白水解\n蛋白pp1a/b，\n进一步水解形\n成16 个非结\n构蛋白。 （何丽红 等，2020）", "points": ["包括病毒吸附、入侵、遗传物质释放、基因组", "S 蛋白与细胞表", "面受体ACE2结合 转录和复制、组装和出芽等过程。", "跨膜丝氨酸蛋白酶2"], "img": "assets/img/bc32ppt/s-83.jpg", "imageExplain": "中文PPT第83页；右侧为从PPT提取的文字，图片保留原始排版。", "fig": "中文PPT：RNA的生物合成和转录后加工.pdf", "page": 83}, {"i": 83, "sec": "第32章 RNA的生物合成和加工 · 中文PPT原图", "title": "第四节 逆转录作用", "notes": "第四节 逆转录作用\n—RNA指导下的DNA的合成", "points": ["—RNA指导下的DNA的合成"], "img": "assets/img/bc32ppt/s-84.jpg", "imageExplain": "中文PPT第84页；右侧为从PPT提取的文字，图片保留原始排版。", "fig": "中文PPT：RNA的生物合成和转录后加工.pdf", "page": 84}, {"i": 84, "sec": "第32章 RNA的生物合成和加工 · 中文PPT原图", "title": "逆转录作用（reverse transcription）", "notes": "College of Life Sciences, CNU\n\n⚫逆转录作用（reverse transcription）\n\n 以RNA为模板，即按照RNA中的核苷\n酸顺序合成DNA的过程。", "points": ["以RNA为模板，即按照RNA中的核苷", "酸顺序合成DNA的过程。"], "img": "assets/img/bc32ppt/s-85.jpg", "imageExplain": "中文PPT第85页；右侧为从PPT提取的文字，图片保留原始排版。", "fig": "中文PPT：RNA的生物合成和转录后加工.pdf", "page": 85}, {"i": 85, "sec": "第32章 RNA的生物合成和加工 · 中文PPT原图", "title": "一、逆转录酶（reverse transcriptase）的发现", "notes": "College of Life Sciences, CNU\n一、逆转录酶（reverse transcriptase）的发现\n\n ⚫ 1964 年，Temin 提出前病毒学说，即在致癌RNA\n 病毒的感染过程中存在一个DNA中间体（前病毒）。\n\n ⚫ 1970年， Temin和Baltimore分别从致癌RNA病毒\n 中发现逆转录酶。\n\n ⚫ 1975年，获诺贝尔生理或医学奖。", "points": ["1964 年，Temin 提出前病毒学说，即在致癌RNA", "病毒的感染过程中存在一个DNA中间体（前病毒）。", "1970年， Temin和Baltimore分别从致癌RNA病毒", "中发现逆转录酶。"], "img": "assets/img/bc32ppt/s-86.jpg", "imageExplain": "中文PPT第86页；右侧为从PPT提取的文字，图片保留原始排版。", "fig": "中文PPT：RNA的生物合成和转录后加工.pdf", "page": 86}, {"i": 86, "sec": "第32章 RNA的生物合成和加工 · 中文PPT原图", "title": "发现肿瘤病毒与细胞遗传", "notes": "College of Life Sciences, CNU\n\n发现肿瘤病毒与细胞遗传\n物质的相互作用\n\n杜尔贝科：证明\nDNA病毒可以嵌\n入基因组", "points": ["物质的相互作用", "杜尔贝科：证明", "DNA病毒可以嵌"], "img": "assets/img/bc32ppt/s-87.jpg", "imageExplain": "中文PPT第87页；右侧为从PPT提取的文字，图片保留原始排版。", "fig": "中文PPT：RNA的生物合成和转录后加工.pdf", "page": 87}, {"i": 87, "sec": "第32章 RNA的生物合成和加工 · 中文PPT原图", "title": "二、逆转录酶的性质", "notes": "College of Life Sciences, CNU\n二、逆转录酶的性质\n\n兼有三种酶活力：\n\nRNA指导的DNA聚合酶活力 •以4种dNTP为底物\n •需要有模板和引物\n 聚合酶\n 活力 （ tRNA）\nDNA指导的DNA聚合酶活力\n •聚合方向： 5→3\n 需Mg2+和还原剂\n核糖核酸酶H的活力\n 水解RNA-DNA杂交分子中的RNA", "points": ["兼有三种酶活力：", "RNA指导的DNA聚合酶活力 •以4种dNTP为底物", "需要有模板和引物", "活力 （ tRNA）"], "img": "assets/img/bc32ppt/s-88.jpg", "imageExplain": "中文PPT第88页；右侧为从PPT提取的文字，图片保留原始排版。", "fig": "中文PPT：RNA的生物合成和转录后加工.pdf", "page": 88}, {"i": 88, "sec": "第32章 RNA的生物合成和加工 · 中文PPT原图", "title": "三、逆转录病毒的基因组", "notes": "College of Life Sciences, CNU\n三、逆转录病毒的基因组\n\n 鼠白血病病毒\n\n• 两条相同的（+）RNA链在靠近5端的区域以氢键结合\n• 基因组两端具有相同的正向重复序列（R）\n• 5 端具有帽子结构，3 端具有多聚腺苷酸。\n• 靠近5 端有1分子宿主tRNA，作为逆转录引物。\n• 典型逆转录病毒基因组：7000-10000核苷酸，携带3个基因\n • gag：编码核心蛋白\n • pol：编码蛋白酶、整合酶、逆转录酶\n • env: 编码被膜蛋白", "points": ["鼠白血病病毒", "两条相同的（+）RNA链在靠近5端的区域以氢键结合", "基因组两端具有相同的正向重复序列（R）", "5 端具有帽子结构，3 端具有多聚腺苷酸。"], "img": "assets/img/bc32ppt/s-89.jpg", "imageExplain": "中文PPT第89页；右侧为从PPT提取的文字，图片保留原始排版。", "fig": "中文PPT：RNA的生物合成和转录后加工.pdf", "page": 89}, {"i": 89, "sec": "第32章 RNA的生物合成和加工 · 中文PPT原图", "title": "编码酪氨酸蛋", "notes": "College of Life Sciences, CNU\n\n 编码酪氨酸蛋\n 癌基因 白激酶，高表\n 达时，导致细\n人类嗜T细胞病毒 胞分裂失控", "points": ["癌基因 白激酶，高表", "达时，导致细", "人类嗜T细胞病毒 胞分裂失控"], "img": "assets/img/bc32ppt/s-90.jpg", "imageExplain": "中文PPT第90页；右侧为从PPT提取的文字，图片保留原始排版。", "fig": "中文PPT：RNA的生物合成和转录后加工.pdf", "page": 90}, {"i": 90, "sec": "第32章 RNA的生物合成和加工 · 中文PPT原图", "title": "四、逆转录过程", "notes": "四、逆转录过程\n +\n 侵染宿主细胞 RNA指导的\n DNA聚合酶\n 病毒RNA RNA-cDNA\n 杂交分子\n\n - - +\n核糖核酸酶H DNA指导的 整合入染色体\n DNA聚合酶 基因组\n DNA 双链DNA\n\n +\n 转录 +\n + 病毒RNA\n +\n\n 翻译\n 自身蛋白质", "points": ["侵染宿主细胞 RNA指导的", "DNA聚合酶", "病毒RNA RNA-cDNA", "核糖核酸酶H DNA指导的 整合入染色体"], "img": "assets/img/bc32ppt/s-91.jpg", "imageExplain": "中文PPT第91页；右侧为从PPT提取的文字，图片保留原始排版。", "fig": "中文PPT：RNA的生物合成和转录后加工.pdf", "page": 91}, {"i": 91, "sec": "第32章 RNA的生物合成和加工 · 中文PPT原图", "title": "病毒颗粒依靠表面蛋白和跨膜蛋白，与宿主细胞融合。", "notes": "College of Life Sciences, CNU\n\n• 病毒颗粒依靠表面蛋白和跨膜蛋白，与宿主细胞融合。\n• 细胞质中，RNA逆转录。cDNA进入细胞核，在整合酶\n 作用下整合到宿主染色体DNA中——前病毒。\n• 前病毒随宿主细胞的DNA复制和转录。", "points": ["细胞质中，RNA逆转录。cDNA进入细胞核，在整合酶", "作用下整合到宿主染色体DNA中——前病毒。", "前病毒随宿主细胞的DNA复制和转录。"], "img": "assets/img/bc32ppt/s-92.jpg", "imageExplain": "中文PPT第92页；右侧为从PPT提取的文字，图片保留原始排版。", "fig": "中文PPT：RNA的生物合成和转录后加工.pdf", "page": 92}, {"i": 92, "sec": "第32章 RNA的生物合成和加工 · 中文PPT原图", "title": "五、逆转录的生物学意义", "notes": "College of Life Sciences, CNU\n五、逆转录的生物学意义\n\n1. 逆转录酶是研究DNA-RNA关系、DNA克隆的重要工具酶\n\n - cDNA的获得\n\n -由cDNA反推RNA的顺序\n\n2. 对逆转录过程的研究，有助于人们了解RNA病毒的致癌机理\n\n3. 揭示HIV等病毒的致病机理，提供防治策略\n\n4. 逆转录病毒可作为信息载体参与基因治疗", "points": ["1. 逆转录酶是研究DNA-RNA关系、DNA克隆的重要工具酶", "cDNA的获得", "由cDNA反推RNA的顺序", "2. 对逆转录过程的研究，有助于人们了解RNA病毒的致癌机理"], "img": "assets/img/bc32ppt/s-93.jpg", "imageExplain": "中文PPT第93页；右侧为从PPT提取的文字，图片保留原始排版。", "fig": "中文PPT：RNA的生物合成和转录后加工.pdf", "page": 93}]}], "mcq": [{"id": "bc32_mcq_1", "modI": 0, "q": "，顺式作用元件是指〈 ). [RA 2019 研]", "o": ["A. 编码基因 5'端侧辟的非编码序列", "B. 编码基因 3'端侧辟的非编码序列", "C. 编码基因以外可影响编码基因表达活性的序列", "D. 启动子不属顺式作用元件"], "a": "C", "e": "", "kp": ""}, {"id": "bc32_mcq_2", "modI": 0, "q": "下列有关 RNA 聚合酶的陈述中，哪一种是正确的? 《 ) [华中农业大学 2002 研]", "o": ["A. 合成多核昔酸链时 RN", "C. RN", "D. RN"], "a": "C", "e": "", "kp": ""}, {"id": "bc32_mcq_3", "modI": 0, "q": "原核生物基因转录终止子在终止点前均有 ( )。[中国科学院 2002 HF]", "o": ["A. [", "B. 多聚人序列", "C. T", "D. "], "a": "A", "e": "", "kp": ""}, {"id": "bc32_mcq_4", "modI": 0, "q": "真核细胞 RNA 帽样结构中最常见的是〈 )。[中国科学院水生所 2009 研]", "o": ["A. m’", "B. m’GpppNmp (Nm) pN", "C. m’UpppNmp (Nm) pN", "D. m’", "E. m’TpppNmp (Nm) PN"], "a": "B", "e": "", "kp": ""}], "judge": [], "fill": [], "term": [], "short": [{"id": "bc32_short_1", "modI": 0, "q": "比较四类聚合酶性质和作用的异同(四类聚合酶是: DNA 指导的 DNA 聚合酶，DNA 指导的 RNA 聚合酶，RNA 指导的 RNA 聚合酶，RNA 指导的 DNA 聚合酶)", "a": "四类聚合酶性质和作用比较如下表所示。 表 32-8 ”四类聚合酶性质和作用的异同 DNA Rass | 一般具有校正或核酸外切酶活性 RNA 聚合酶的作用是转录 RNA; DNA 指导的 . Sas 会 加 在某些 RNA 病毒中存在 让人生和信人人 DNA RNA SRABRS ADA IVREAIAIUTEU, | (Si, EASE THEN 9-08; RNA 指导的 OO 鲜合成的方向都是 5一3 H+ +O =. os RNA RSH RNA 复制的错误率较高; RNA 复制梅只是 轩除聚合 DNA 外还有其他功能 . 特异地对病毒的 RNA 起作用，而宿主细胞 的 RNA 一般并不进行复制 DNA 聚合酶 | RNA 酶、DNA 指导的 DNA 聚合酶活性", "kps": "四类聚合酶：模板/产物/方向/校对/功能", "freq": "常考", "prio": "A", "req": "理解", "src": "朱圣庚第4版第32章笔记", "e": "DNA指导DNA聚合酶：模板DNA→DNA，5′→3′，有校对；DNA指导RNA聚合酶：DNA→RNA，5′→3′，无校对；RNA指导RNA聚合酶：RNA→RNA，病毒RNA复制；RNA指导DNA聚合酶：逆转录酶，RNA→DNA。共同：5′→3′合成、需模板/引物（RNA聚合酶不需引物）。"}, {"id": "bc32_short_2", "modI": 0, "q": "原核生物 RNA 聚合酶是如何找到启动子的? 真核生物聚合酶与之相比有何异同?", "a": "CL) 原核生物 RNA 聚合酶是在 8 亚基引导下识别并结合到启动子上的，没有8 亚基的 RNA 聚合 酶只具有使已开始合成的 RNA 延长的功能，而不具备起始功能。8 亚基罕而长，分 4 个区,位于核心酶表 面。不同类型的 8 亚基识别不同类型的启动子。 (2)真核生物 RNA 聚合酶与原核生物 RNA 聚合酶最主要的区别是真核生物 RNA 聚合酶自身不能识 别和结合到启动子上,而需要在启动子上由转录因子和RNA聚合酶装配成活性转录复合物才能起始转录。", "kps": "原核σ因子识别启动子；真核需转录因子组装前起始复合物", "freq": "常考", "prio": "A", "req": "理解", "src": "朱圣庚第4版第32章笔记", "e": "原核RNA聚合酶全酶由σ因子识别启动子（-35/-10），核心酶延伸；真核RNA聚合酶不能单独识别启动子，需TFIID/TBP等通用转录因子和激活因子组装前起始复合物。"}, {"id": "bc32_short_3", "modI": 0, "q": "何谓启动子? 保守序列与共有序列的概念是否一样? Pribnow 框与启动子之间是何关系?", "a": "CD) 启动子是指 RNA 聚合酶识别、结合和开始转录的一段 DNA 序列。它含有 RNA 聚合酶特异 性结合和转录起始所需的保守序列，多数位于结构基因转录起始点的上游，启动子本身不被转录。RNA BE 合酶与启动子的相互作用是转录起始的关键。 (2) 保守序列与共有序列的概念的含义基本相同。保守序列间相似度高，但不一定相同，而共有序 列是相同的，共有序列可理解为是一种特殊的保守序列。 (3) Pribnow 框与启动子之间的关系: Pribnow 框是原核生物启动子的保守序列之一，是启动子序列的一部分，位于转录起始位点上游 5一 10bp 处，一般由 6一8 个碱基组成富含 AT 的保守序列，有助于 DNA 局部双链解开。", "kps": "启动子=RNA聚合酶识别/结合/起始序列；保守/共有；Pribnow框是-10区", "freq": "常考", "prio": "A", "req": "理解", "src": "朱圣庚第4版第32章笔记", "e": "启动子是RNA聚合酶识别、结合并起始转录的DNA序列，本身不转录。保守序列相似但不相同；共有序列是保守序列的特例。Pribnow框是原核启动子-10区富含AT的保守序列，帮助解链。"}, {"id": "bc32_short_4", "modI": 0, "q": "真核生物三类启动子各有何结构特点?", "a": "真核生物有三种 RNA 聚合酶: RNA 聚合酶I、I、II，与之对应有三种类型的启动子。 (1) 类型[启动子。 I类启动子负责转录编码核糖体RNA的多顺反子转录。兰椎动物RNA聚合酶[的启动子由两部分组成， 包括转录起点附近的核心启动子，和起点 5上游 100bp 左右的上游控制元件 〈UCE)。核心启动子从一45 到十20，负责转录的起始。UCE 从一180 延伸到一107，此区可增加核心元件的转录起始的效率。 (2) 类型I[启动子。 RNA 聚合酶I的启动子有三个保守区。 (TATA 框 (Hogness 框): 中心在一25 至一30，长度 7bp 左右。 碱基频率: TPAPTAS AS? (TP) ASAN CT?) (全为AT，少数含有一个 G-C 对)。 此序列功能: 使 DNA 双链解开，并决定转录的起点位置，失去 TATA 框，转录将可能在许多位点上 Fri. TATA 框的改变或缺失，直接影响 DNA 与酶的结合程度，会使转录起始点偏移。因此，TAIA 是绝 大多数真核基因正确表达所必需的。 QCAAT HE: 中心在一75 处，9bp，共有序列为 GGT (G) CAATCT. 功能: 与 RNA 聚合酶结合。 GGC ti: 在 CAAT 框上游，序列为 GGGCGG，与某些转录因子结合。 (3) 类型II启动子。 5S RNA 和tRNA 都属于 RNA 聚合酶本启动子，但它们比较特殊，位于起始位点的下游的转录区内， 因此也称为下游启动子或基因内启动子或称为内部控制区 (ICR)。snRNA 基因的启动子和常见的启动子 -样位于起始位点的上游，称为上游启动子。下游启动子又可分为1型和2型。1 型内部启动子含有两个 分开的 boxA (TGGCNNAGTGG) 和 boxC (CGGTCGANNCC) 序列。2 型内部启动子中 boxA 和 boxB 之 间的距离较宽。通常有功能的此类启动子中的两个 box 就不能紧紧连在一起。RNA 聚合酶II的上游启动子 有 3 个上游元件，这些元件仅在 snRNA 启动子中被发现，有的 snRNA 是由 RNA RAAB Ha, AE HH RNA 聚合酶村转录。这些上游元件在一定程度上和 pol I的启动子相似。 5，何谓终止子和终止因子? 依赖于 rho 的转录终止信号是如何传递给 RNA 聚合酶的? 答: (1) Bik FAA IFAT: 终止子是指提供转录终止信号的一段 DNA 序列。终止子根据是否依赖 p 因子的作用分为两类: 不依 RF p 的终止子和依赖于 p 的终止子。两类终止子有共同的序列特征: 在转录终止点前有一段回文序列， 回文序列的两个重复部分〈每个7一20bp) 由几个不重复的 bp 节段隔开。 终止因子是指协助 RNA 育合酶识别终止子的蛋白质辅助因子。这些辅助因子的功能也可能被某些蛋 白质阻止，造成 RNA 聚合酶越过终止子继续转录。 (2) 转录终止信号传递给 RNA 聚合酶的过程: 依赖于 rho 的终止子必须在 rho 因子存在时才发生终止作用。rho 结合在新生成的RNA 链上，借助消 解 NTP 所获得的能量沿 RNA 链移动。RNA 酶遇到终止子时发生和暂停，使 rho 得以追上酶，rho 因子具有 RNA-DNA 解螺旋酶的活力，造成 RNA 的释放。", "kps": "Pol I：核心+UCE；Pol II：TATA/CAAT/GC；Pol III：下游ICR/boxA/B/C", "freq": "常考", "prio": "A", "req": "理解", "src": "朱圣庚第4版第32章笔记", "e": "真核三类启动子：Pol I（rRNA）核心启动子+上游控制元件UCE；Pol II（mRNA）TATA框、CAAT框、GC框；Pol III（5S/tRNA）下游内部控制区boxA/B/C，snRNA可有上游启动子。"}, {"id": "bc32_short_5", "modI": 0, "q": "何谓时序调控? 何为适应调控? 分别对原核生物和真核生物的转录调控举例加以说明。", "a": "CL) 时序调控和适应调控; 时序调控是指在细胞的生长、发育和分化过程中，遗传信息的表达可按一定的时间程序发生变化。 适应调控是指在细胞的生长、发育和分化过程中，遗传信息的表达会随着细胞内外环境条件的改变而 加以调整。 (2) 举例如下: 包原核生物的转录调控。 原核生物主要是通过操纵子对转录进行调控。在没有乳糖存在时，乳糖操纵子处于阻过状态 。此时， I工基因列在P 启动序列操纵下表达的乳糖阻过蛋白与 O 序列结合，故阻断转录启动。阻遏蛋白的阻过作用 并非绝对，偶有阻过蛋白与 O 序列解聚。因此，每个细胞中可能会有少数分子 B-半乳糖昔酶、透酶生成。 当有乳糖存在时, 乳糖操纵子即可被诱导。 真正的诱导剂并非乳糖本身。 乳糖经透酶催化、转运进入细胞， 再经原先存在于细胞中的少数 B-半乳糖苷酶催化, 转变为半乳糖。 后者作为一种诱导剂分子结合阻过蛋白， 使蛋白构型变化，导致阻过蛋白与 O 序列解离、发生转录，使 B-半乳糖昔酶分子增加 1000 倍。 @@真核生物的转录调控。 真核生物的转录调控依赖于基本转录因子 TFID 的作用。真核 RNA 聚合酶II[不能单独识别、结合启动 子，而是先由基本转录因子 TFIID 组成成分 TBP 识别 TATA 盒或启动元件，并有 TFIIA 参与结合，形成 TFIID-启动子复合物，继而在 TGIIAE 等参与下，RNA 聚合酶I[与 TFIID、TEFIIB 聚合，形成一个功能性的 前起始复合物。在几种基本转录因子中，TEFIID 是唯一具有位点特异的 DNA 结合能力的转录因子，在上 述有序的组装过程起关键性指导作用。 这样形成的前起始复合物尚不稳定, 也不能有效启动 mRMA 转录。 然后由结合在增强子上的转录激活因子直接或间接与 TFIID 结合，从而影响前起始复合物的形成、稳定性 以及RNA 聚合酶的活性。", "kps": "终止子=终止信号；ρ依赖/非依赖；ρ沿RNA追酶、解旋释放", "freq": "常考", "prio": "A", "req": "理解", "src": "朱圣庚第4版第32章笔记", "e": "终止子是提供转录终止信号的DNA序列；分不依赖ρ和依赖ρ两类，常有回文序列。ρ因子结合新生RNA，水解NTP沿RNA移动，追上暂停的RNA聚合酶，利用解旋酶活性释放RNA。"}, {"id": "bc32_short_6", "modI": 0, "q": "简要说明原核生物和真核生物转录调控的主要特点。", "a": "转录水平的调控是遗传信息表达调控的关键环节，原核生物和真核生物转录调控的主要特点有: (1) 原核生物功能相关基因和常组织在一起构成操纵子，作为基因表达和调节的单位，真核生物不组 成操纵子，每个基因都有自己的基本启动子和调节单元，单独进行转录，相关基因间也可进行协同调节。 (2) 原核生物只有少数种类的调节单元，真核生物调节单元众多，包括组成型元件、可诱导元件以 及增强子等。 (3) 无论是原核还是真核生物，其转录受反式调节因子所调节。 (4) 真核生物的转录调节涉及到染色质改型，原核生物不存在染色质水平的调节。", "kps": "原核操纵子/少数调节；真核独立基因/多元件/染色质", "freq": "常考", "prio": "A", "req": "理解", "src": "朱圣庚第4版第32章笔记", "e": "原核功能相关基因组成操纵子，调节单元少；真核基因独立转录，有增强子/沉默子/绝缘子等多种元件，受反式因子调节，并涉及染色质重塑。"}, {"id": "bc32_short_7", "modI": 0, "q": "转录调节因子的结构有何特点?", "a": "转录调节因子分为基本转录因子和特异转录因子。不同的转录调节因子有不同的特点。转录调节 因子通常包括 DNA 结合域、转录激活域和二聚化结构域，各个结构域的特点如下: (1) DNA 结合域通常由 60一100 个氨基酸残基组成。最常见的 DNA 结合域结构形式是锌指结构和 碱性 u 螺旋。类似的碱性 DNA 结合域多见于碱性亮氨酸拉链和碱性螺旋-环-螺旋。 (2) 转录激活域由 30一100 个氨基酸残基组成。 根据氨基酸组成特点,转录激活域又有酸性激活域、 FE ADEN TS KS Be HG AP Bh FX Se. (3) 二聚化结构域中的二聚化作用与亮氨酸拉链、螺旋-环-螺旋结构有关。 9，比较启动子上游元件、增强子和绝缘子的作用特点。 答: CD) 启动子上游元件: 启动子上游元件是位于核心启动子的上游，能结合反式因子，参与调控基因转录的序列，它们由许多 短的共有序列所组成。真核生物有较多的启动子上游元件，包括组成型元件、可诱导元件、增强子和沉默 子等。 (2) 增强子: 增强子是远离转录起始点、决定基因的时间、空间特异性表达、增强启动子转录活性的 DNA 序列， 其发挥作用的方式通常与方向、距离无关，可位于转录起始点的上游或下游。从功能上讲，没有增强子存 在，启动子通常不能表现活性;没有启动子时，增强子也无法发挥作用。 (3) 绝缘子: 绝缘子是一种长约几十到几百个核昔酸对的调控序列，通常位于启动子邻近基因的正调控元件 增强 子) 或负调控元件〈沉默子) 之间。绝缘子本身对基因的表达既没有正效应，也没有负效应，其作用只是 不让其他调控元件对基因的活化效应或失活效应发生作用。", "kps": "DNA结合域/转录激活域/二聚化域；锌指/亮氨酸拉链/HLH", "freq": "常考", "prio": "A", "req": "理解", "src": "朱圣庚第4版第32章笔记", "e": "转录因子模块：DNA结合域（锌指、碱性α螺旋、bZIP、bHLH）、转录激活域（酸性、富含Gln/Pro）、二聚化域（亮氨酸拉链、HLH）。模块组合决定识别和调控。"}, {"id": "bc32_short_8", "modI": 0, "q": "什么是染色质的结构域? 它有哪些控制位点?", "a": "CL) 染色质的结构域是指染色质上具有特定结构和功能的区域，它们对遗传信息的表达也有一定 的调控作用。 (2) 它有 3 种类型的控制位点 钙基因座控制区: 以组织特异性及拷贝数依赖的方式将相关基因的表达增强到生理学水平的异位染色 质位点。 加绝缘子: 通常位于启动子同正调控元件〈增强子) 或负调控因子 〈为异染色质) 之间的一种调控序 列。绝缘子本身对基因的表达既没有正效应，也没有负效应，其作用只是不让其他调控元件对基因的活化 效应或失活效应发生作用。 @@基质附着位点: 也称核骨架结合区，是存在于真核细胞染色体中的一段与基质特异结合的 DNA FP 列。 Ll. 目前有哪些重要的 RNA 合成抑制剂已在临床上用作抗癌药物、抗病毒药物和治疗艾滋病的药物? 其作用机制是什么? 答: RNA 合成抑制剂能抑制核苷酸或核酸的生物合成，常被用作抗病毒和抗肿瘤药物，目前在临床上 应用的 RNA 合成抑制剂可分为 3 类; (1) 味吟和喀啶类似物: 如 6-玖基味哈、5-尿喀喧等，它们可作为核昔酸代谢持抗物而抑制核苷酸 前体的合成,或者通过挫入到核酸分子中去,形成异常的DNA或 RNA, 从而影响核酸的功能并导致突变。。 (2) DNA 模板功能的抑制物， 如烷化剂、放线菌素等，它们通过与 DNA 结合而改变 DNA 的功能。 如烷化剂使鸟味叭烷基化后，鸟味叭不稳定，易被水解脱落下来，留下的空隙可能干扰 DNA 复制或引起 错误碱基的摊入。 (3) RNA 酶抑制剂， 如利福霉素、利链菌素等，它们与 RNA 酶结合并影响其功能。", "kps": "染色质结构域；基因座控制区/绝缘子/基质附着区", "freq": "常考", "prio": "A", "req": "理解", "src": "朱圣庚第4版第32章笔记", "e": "染色质结构域是特定结构/功能区域，控制位点：基因座控制区LCR（增强相关基因）、绝缘子（阻断增强子/异染色质）、基质附着区MAR（结合核基质）。"}, {"id": "bc32_short_9", "modI": 0, "q": "为什么 RNA 转录后加工比任何生物大分子合成后的加工过程都更复杂?", "a": "RNA 转录后加工是指由 RNA 聚合酶合成的原初转录物往往需要经过一系列的变化，包括链的裂 解、5'端与 3'端的切除、未端特殊结构的形成、核背的修饰和糖苷键的改变以及剪接和编辑等信息加工过 程，才能转变为成熟的 RNA 分子。RNA 转录后加工过程更复杂的原因有: (1) RNA 特别是真核生物的 RNA 分子，在转录后必须在其头和尾部加上帽子和多聚尾巴结构。 (2) 真核生物基因往往是被内含子隔断的断裂基因，在转录后必须进行剪切、拼接和重编码。因此 与其他生物大分子相比，其合成后的加工过程都更复杂。 (3) 真核生物中还能通过不同的加工方式，表达出不同的信息。", "kps": "加帽/加尾/剪接/编辑/修饰；真核断裂基因", "freq": "常考", "prio": "A", "req": "理解", "src": "朱圣庚第4版第32章笔记", "e": "RNA加工复杂因为：①5′加帽、3′加polyA；②真核基因含内含子，需剪接；③可选择性剪接/编辑产生多种产物；④碱基修饰。比蛋白质/多糖加工更复杂。"}, {"id": "bc32_short_10", "modI": 0, "q": "isi snoRNA 的结构和作用。", "a": "(1) snoRNA 的结构: 核仁小分子 RNA (snoRNA)，是近来生物学研究的热点，snoRNA 不是由其单独的基因所编码，而是 由切除的内含子片段加工而成。富含 AT，有 boxC 和 boxD 结构元素。核仁小分子 RNA 有多种功能，反 义 snoRNA 指导 rRNA 核糖甲基化。 (2) snoRNA 的作用: 核仁小分子 RNA 与其他 RNA 的处理和修饰有关，与 TRNA 前体的加工有关，包括断裂、甲基化、假尿喀 喧核背的形成。核仁小分子 RNA 是一个与特性化的非编码 RNA 相关的大家族。", "kps": "snoRNA：boxC/D；指导rRNA甲基化/假尿苷化；来自内含子", "freq": "常考", "prio": "A", "req": "理解", "src": "朱圣庚第4版第32章笔记", "e": "snoRNA是核仁小RNA，常由内含子加工产生，含boxC/D或boxH/ACA；与蛋白形成snoRNP，通过反义配对指导rRNA的2′-O-甲基化或假尿苷化，参与rRNA加工。"}, {"id": "bc32_short_11", "modI": 0, "q": "由 hnRNA 转变为 mRNA 需经过何种加工? 这些加工有何意义?", "a": "hnRNA 是核内不均一 RNA, 是 mRNA 的原初转录物在核内加工过程中形成分子大小不等的中间 物。 (1) 由 hnRNA 转变成 mRNA 的加工过程包括; GD5'端形成特殊的帽子结构 C m7\"G5'ppp5'NmpNp- ) 。 QLERENY 3'端切断并加上多聚腺音酸 (poly AD 尾巴。 Qik TH BREA SLI. QE A PRE BE PELL. (2) 每种加工的意义如下: GD5'端形成特殊的帽子结构 ( m\"G5ppp5NmpNp- ) 能保护 RNA 转录物，并给出 5端标记，有助于前 接、运输和翻译各类功能复合物的识别，以协助完成这些功能。 QtEKENY 3'端切断并加上多聚腺苷酸 (poly AD 尾巴可以起某种缓冲作用，防止外切核酸酶对 mRNA 信息序列的降解作用。 图通过剪接除去内含子序列是真核生物断裂基因的转录产物必需的加工过程，去除插入部分，使编码 区成为连续序列，这是基因表达调控的一个重要环节。 OPE A MBE HE PEC AT ER mRNA 前体的加工起识别作用。", "kps": "hnRNA→mRNA：加帽、加尾、剪接、编辑；保护/稳定/翻译", "freq": "常考", "prio": "A", "req": "理解", "src": "朱圣庚第4版第32章笔记", "e": "hnRNA加工：5′加m7G帽（保护、识别）、3′加polyA（稳定、防降解）、剪接去内含子（形成连续编码区）、RNA编辑/修饰。意义：产生成熟mRNA，稳定、可翻译、增加多样性。"}, {"id": "bc32_short_12", "modI": 0, "q": "何谓 RNA 剪接? 为何要先转录内含子，然后再将其切除?", "a": "(1) RNA 剪接是指从 DNA 模板链转录出的最初产物中除去内含子，并将外显子连接起来形成连 续的 RNA 分子的过程。这是由于大多数真核基因都是断裂基因，需要剪切、连接后形成有功能的片段。 RNA 的剪接是基因表达凋控的一个重要环节。 (2) 关于内含子的功能，有 2 种不同看法: @内含子是在进化中出现和消失的，内含子如果有功能，只不过是有利于物种的进化选择。例如，细 菌丢失了内含子，可以使染色体变小和复制速度加快。真核生物保留内含子，则可以产生外显子移动，有 利于真核生物在适应环境改变时合成功能上有差异而结构上只有微小差异的蛋白质。 加内含子在基因表达中可能有调控功能。例如，现在已知道某些遗传性疾病，其变异是发生在内含子 而不在外显子。有些内含子在调控基因表达的过程中起作用，有些内含子还能编码酶。", "kps": "剪接=去内含子连外显子；内含子可调控/进化/选择性剪接", "freq": "常考", "prio": "A", "req": "理解", "src": "朱圣庚第4版第32章笔记", "e": "RNA剪接是从前体去除内含子、连接外显子。先转录内含子再切除的原因：内含子可调控表达、通过选择性剪接产生多种蛋白、促进外显子重组/进化；不是单纯“垃圾”。"}], "calc": [], "preview": {"main": "32.1 复习笔记\n一、DNA 指导下 RNA 的合成\n1. 概述\n在 DNA 指导下，以 DNA 的一条链为模板在 RNA 聚合酶的催化下，以 4 种核糖核苷三磷酸 (NTP)\n为底物，按照碱基互补配对原则，形成一条与 DNA 链一定区域互补的 RNA 链的过程称为转录。\n2. DNA 指导的 RNA RABE\nDNA 指导的 RNA 聚合酶的作用特点:\nC1) RNA 聚合酶以 4 种核糖核苷三磷酸为底物，DNA WHER, Mg? 促进聚合反应。\n(2) RNA 聚合酶无需引物，直接在模板上合成RNA 链，R", "questions": ["比较四类聚合酶性质和作用的异同(四类聚合酶是: DNA 指导的 DNA 聚合酶，DNA 指导的 RNA 聚合酶，RNA 指导的 RNA 聚合酶，RNA 指导的 ", "原核生物 RNA 聚合酶是如何找到启动子的? 真核生物聚合酶与之相比有何异同?", "何谓启动子? 保守序列与共有序列的概念是否一样? Pribnow 框与启动子之间是何关系?"]}, "pptDeck": "bc32ppt", "pptLang": "中文"};
